window.CC.p.push({n:8,view:"<section class=\"view\" id=\"p8\" hidden style=\"--c:#1e6fd9\"><h1><i>8</i>Obstetrics &amp; Gynecology</h1><p class=\"lead\">30 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 8A</h3><div class=\"card\" data-u=\"u172\"><button class=\"open\" data-u=\"u172\"><b>Case 1</b><span>Antenatal Care, Pregnancy Dating &amp; Physiological Adaptations</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Antenatal+Care%2C+Pregnancy+Dating+%26+Physiological+Adaptations\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u173\"><button class=\"open\" data-u=\"u173\"><b>Case 2</b><span>Nausea &amp; Vomiting of Pregnancy vs. Hyperemesis Gravidarum</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nausea+%26+Vomiting+of+Pregnancy+vs.+Hyperemesis+Gravidarum\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u174\"><button class=\"open\" data-u=\"u174\"><b>Case 3</b><span>Ectopic Pregnancy (#1 CAUSE OF 1ST-TRIMESTER MATERNAL MORTALITY!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ectopic+Pregnancy+%28%231+CAUSE+OF+1ST-TRIMESTER+MATERNAL+MORTALITY%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u175\"><button class=\"open\" data-u=\"u175\"><b>Case 4</b><span>Spontaneous Abortion (MISCARRIAGE — 6 CLINICAL TYPES)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Spontaneous+Abortion+%28MISCARRIAGE+%E2%80%94+6+CLINICAL+TYPES%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u176\"><button class=\"open\" data-u=\"u176\"><b>Case 5</b><span>Gestational Trophoblastic Disease (HYDATIDIFORM MOLE)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gestational+Trophoblastic+Disease+%28HYDATIDIFORM+MOLE%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u177\"><button class=\"open\" data-u=\"u177\"><b>Case 6</b><span>Placenta Previa &amp; Vasa Previa (PAINLESS 3RD-TRIMESTER BLEEDING!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Placenta+Previa+%26+Vasa+Previa+%28PAINLESS+3RD-TRIMESTER+BLEEDING%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u178\"><button class=\"open\" data-u=\"u178\"><b>Case 7</b><span>Placental Abruption &amp; Uterine Rupture (PAINFUL BLEEDING!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Placental+Abruption+%26+Uterine+Rupture+%28PAINFUL+BLEEDING%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u179\"><button class=\"open\" data-u=\"u179\"><b>Case 8</b><span>Hypertensive Disorders of Pregnancy (PREECLAMPSIA, ECLAMPSIA &amp; HELLP)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertensive+Disorders+of+Pregnancy+%28PREECLAMPSIA%2C+ECLAMPSIA+%26+HELLP%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u180\"><button class=\"open\" data-u=\"u180\"><b>Case 9</b><span>Gestational Diabetes Mellitus (GDM)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gestational+Diabetes+Mellitus+%28GDM%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u181\"><button class=\"open\" data-u=\"u181\"><b>Case 10</b><span>RH Isoimmunization &amp; Anti-D (RHOGAM) Prophylaxis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=RH+Isoimmunization+%26+Anti-D+%28RHOGAM%29+Prophylaxis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u182\"><button class=\"open\" data-u=\"u182\"><b>Case 11</b><span>Preterm Labor (PTL) &amp; Preterm Premature Rupture of Membranes (PPROM)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Preterm+Labor+%28PTL%29+%26+Preterm+Premature+Rupture+of+Membranes+%28PPROM%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u183\"><button class=\"open\" data-u=\"u183\"><b>Case 12</b><span>Fetal Heart Rate Monitoring (CTG) &amp; Amniotic Fluid Disorders</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Fetal+Heart+Rate+Monitoring+%28CTG%29+%26+Amniotic+Fluid+Disorders\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u184\"><button class=\"open\" data-u=\"u184\"><b>Case 13</b><span>Normal Labor, Shoulder Dystocia &amp; Umbilical Cord Prolapse</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Normal+Labor%2C+Shoulder+Dystocia+%26+Umbilical+Cord+Prolapse\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u185\"><button class=\"open\" data-u=\"u185\"><b>Case 14</b><span>Postpartum Hemorrhage (PPH — &quot;THE 4 Ts&quot;)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Postpartum+Hemorrhage+%28PPH+%E2%80%94+%22THE+4+Ts%22%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u186\"><button class=\"open\" data-u=\"u186\"><b>Case 15</b><span>Postpartum Fever, Mastitis &amp; Peripartum VTE</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Postpartum+Fever%2C+Mastitis+%26+Peripartum+VTE\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 8B</h3><div class=\"card\" data-u=\"u187\"><button class=\"open\" data-u=\"u187\"><b>Case 16</b><span>Abnormal Uterine Bleeding (AUB — PALM-COEIN)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Abnormal+Uterine+Bleeding+%28AUB+%E2%80%94+PALM-COEIN%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u188\"><button class=\"open\" data-u=\"u188\"><b>Case 17</b><span>Amenorrhea (PRIMARY &amp; SECONDARY ALGORITHM)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Amenorrhea+%28PRIMARY+%26+SECONDARY+ALGORITHM%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u189\"><button class=\"open\" data-u=\"u189\"><b>Case 18</b><span>Polycystic Ovary Syndrome (PCOS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Polycystic+Ovary+Syndrome+%28PCOS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u190\"><button class=\"open\" data-u=\"u190\"><b>Case 19</b><span>Dysmenorrhea, Endometriosis &amp; Adenomyosis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dysmenorrhea%2C+Endometriosis+%26+Adenomyosis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u191\"><button class=\"open\" data-u=\"u191\"><b>Case 20</b><span>Uterine Leiomyomas (FIBROIDS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Uterine+Leiomyomas+%28FIBROIDS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u192\"><button class=\"open\" data-u=\"u192\"><b>Case 21</b><span>Pelvic Inflammatory Disease (PID) &amp; Tubo-Ovarian Abscess (TOA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pelvic+Inflammatory+Disease+%28PID%29+%26+Tubo-Ovarian+Abscess+%28TOA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u193\"><button class=\"open\" data-u=\"u193\"><b>Case 22</b><span>Vaginitis &amp; Vaginal Discharge Differentiation</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vaginitis+%26+Vaginal+Discharge+Differentiation\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u194\"><button class=\"open\" data-u=\"u194\"><b>Case 23</b><span>Ovarian Cysts &amp; Ovarian Torsion</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ovarian+Cysts+%26+Ovarian+Torsion\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u195\"><button class=\"open\" data-u=\"u195\"><b>Case 24</b><span>Pelvic Organ Prolapse (POP) &amp; Female Urinary Incontinence</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pelvic+Organ+Prolapse+%28POP%29+%26+Female+Urinary+Incontinence\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u196\"><button class=\"open\" data-u=\"u196\"><b>Case 25</b><span>Infertility Evaluation (BASIC WORKUP)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infertility+Evaluation+%28BASIC+WORKUP%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u197\"><button class=\"open\" data-u=\"u197\"><b>Case 26</b><span>Contraception Mastery (WHO MEC SAFETY RULES!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Contraception+Mastery+%28WHO+MEC+SAFETY+RULES%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u198\"><button class=\"open\" data-u=\"u198\"><b>Case 27</b><span>Menopause, HRT &amp; Postmenopausal Bleeding (PMB)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Menopause%2C+HRT+%26+Postmenopausal+Bleeding+%28PMB%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u199\"><button class=\"open\" data-u=\"u199\"><b>Case 28</b><span>Cervical Cancer Screening &amp; Cervical Carcinoma</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cervical+Cancer+Screening+%26+Cervical+Carcinoma\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u200\"><button class=\"open\" data-u=\"u200\"><b>Case 29</b><span>Endometrial Carcinoma vs. Ovarian Carcinoma</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Endometrial+Carcinoma+vs.+Ovarian+Carcinoma\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u201\"><button class=\"open\" data-u=\"u201\"><b>Case 30</b><span>Breast Disorders &amp; Breast Cancer Screening / RED Flags</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Breast+Disorders+%26+Breast+Cancer+Screening+%2F+RED+Flags\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u172\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Antenatal Care, Pregnancy Dating &amp; Physiological Adaptations</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Antenatal+Care%2C+Pregnancy+Dating+%26+Physiological+Adaptations\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Pregnancy Confirmation</b></h3><p>Comprehensive maternal-fetal surveillance from conception through delivery.</p>\n<ul>\n<li class=\"l1\"><b>Diagnosis:</b> Urine/Serum <mark class=\"hl mech\"><b>β-hCG</b></mark> (Beta-Human Chorionic Gonadotropin — doubles every <b>48 hours</b> in early normal intrauterine pregnancy!) + <b>TVUS</b> (Transvaginal Ultrasound — gestational sac visible at β-hCG <b>1,500–2,000 mIU/mL</b> [5 wks]; fetal pole + cardiac activity by 6 wks!).</li>\n<li class=\"l1\"><b>Dating &amp; Naegele’s Rule:</b> <b>EDD</b> (Estimated Date of Delivery) = <b>LMP</b> (Last Menstrual Period) <b>+ 7 days − 3 months + 1 year</b> (most accurate if confirmed by <b>1st-Trimester Crown-Rump Length [CRL] Ultrasound</b>!).</li>\n</ul><h3><b>2. Physiological Changes of Pregnancy (CRITICAL SO YOU DON'T MISINTERPRET NORMAL LABS!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Cardiovascular:</b> <b>Plasma volume increases ~45–50%</b> while RBC mass increases only ~20–30% -&gt; <b>Physiologic Dilutional Anemia</b> (normal Hb ≥ 11.0 g/dL in 1st/3rd trim, ≥ 10.5 in 2nd trim!); <b>Cardiac Output rises ~40–50%</b>; <b>SVR</b> (Systemic Vascular Resistance) &amp; <b>BP drop in 2nd trimester</b> (nadir ~20–24 wks); <b>Supine Hypotension Syndrome</b> (&gt; 20 wks: gravid uterus compresses <b>IVC</b> [Inferior Vena Cava] when lying flat -&gt; <b>place patient in Left Lateral Tilt</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hematologic:</b> <b>Hypercoagulable State</b> (↑ Factors VII, VIII, X, Fibrinogen; ↓ Protein S -&gt; 5× higher <mark class=\"hl lab\"><b>DVT/PE</b></mark> risk!); <b>Physiologic Leukocytosis</b> (WBC up to 14,000– 16,000/µL normal in pregnancy/labor!); <b>Mild Gestational Thrombocytopenia</b> (platelets 100,000–150,000 near term).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Renal &amp; Respiratory:</b> <b>↑ GFR by ~50%</b> -&gt; <b>LOWER Normal Serum Creatinine (0.4–0.8 mg/dL)</b> (a Creatinine of 1.1 mg/dL in pregnancy is <b>abnormal renal injury!</b>); physiologic hydronephrosis (<b>Right &gt; Left</b>); <b>Progesterone-driven hyperventilation</b> -&gt; mild <b>Chronic Respiratory Alkalosis</b> (normal PaCO2 28–32 mmHg!).</span></p><h3><b>3. Essential Routine Antenatal Screening &amp; Supplementation</b></h3><ul>\n<li class=\"l1\"><b>Supplements:</b> <b>Folic Acid 400–800 mcg/day</b> starting <b>pre-conception through 1st trimester</b> (<b>4 mg/day</b> if prior <b>Neural Tube Defect</b> or on Valproate/Carbamazepine!) + <b>Elemental Iron (30–60 mg/day)</b> + <b>Calcium (if low dietary intake)</b> + Vitamin D!</li>\n<li class=\"l1\"><b>Mandatory Labs:</b> Blood Group &amp; <b>Rh Type</b> (+ Antibody screen), <mark class=\"hl mech\"><b>CBC</b></mark> , <mark class=\"hl mech\"><b>HbA1c / Early Glucose</b></mark> (if obese/risk -&gt; universal <b>OGTT at 24–28 weeks</b>!), <mark class=\"hl mech\"><b>Urinalysis + Urine Culture</b></mark> (treat <b>Asymptomatic Bacteriuria</b> in pregnancy to prevent Pyelonephritis!), <mark class=\"hl mech\"><b>HBsAg, HIV, Syphilis (RPR), Rubella IgG</b></mark> , <mark class=\"hl lab\"><b>GBS</b></mark> (Group B <i>Streptococcus</i>) <b>Rectovaginal Swab at 36–37 Weeks</b>!</li>\n<li class=\"l1\"><b>Vaccines SAFE &amp; Recommended in Pregnancy:</b> <b>Tdap</b> (every pregnancy at <b>27–36 weeks</b> to protect newborn from Pertussis!), <b>Inactivated Influenza</b>, <b>RSV</b> (32–36 wks). <i>(AVOID Live Vaccines: MMR, Varicella, BCG!).</i></li>\n</ul><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u173\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u173\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Nausea &amp; Vomiting of Pregnancy vs. Hyperemesis Gravidarum</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Nausea+%26+Vomiting+of+Pregnancy+vs.+Hyperemesis+Gravidarum\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Etiology</b></h3><ul>\n<li class=\"l1\"><b>NVP</b> (Nausea &amp; Vomiting of Pregnancy / \"Morning Sickness\"): Common, mild nausea/vomiting starting <b>5–6 weeks</b>, peaking at <b>9–10 weeks</b>, resolving by <b>16–20 weeks</b> without dehydration or weight loss.</li>\n<li class=\"l1\"><b>Hyperemesis Gravidarum (HG):</b> Severe, persistent intractable vomiting causing <b>≥ 5% Pre-Pregnancy Weight Loss, Dehydration, Ketonuria, &amp; Electrolyte Imbalances</b>!</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Risk Factors (Linked to High β-hCG / Estrogen):</b></mark> <b>Multiple Gestation (Twins)</b>, <b>Hydatidiform Mole</b> (<b>ALWAYS do Pelvic Ultrasound in severe HG!</b>), Nulliparity, Prior HG.</li>\n</ul><h3><b>2. Investigations &amp; Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\"><b>Labs:</b> Urine Dipstick (<b>Ketonuria</b>), <b>BMP</b> (Hypokalemic hypochloremic metabolic alkalosis!), <mark class=\"hl mech\"><b>LFTs</b></mark> (mild transient ALT/AST rise common), <mark class=\"hl mech\"><b>TSH/Free T4</b></mark> (high hCG weakly stimulates TSH receptors causing transient <i>Gestational Thyrotoxicosis</i> — do NOT give antithyroid drugs unless Graves’!).</li>\n<li class=\"l1\"><b>MUST RULE OUT:</b> <b>Molar Pregnancy / Twins (Ultrasound!)</b>, <b>Acute Pyelonephritis</b>, <mark class=\"hl lab\"><b>Cholecystitis</b></mark> , <b>Pancreatitis</b>, <mark class=\"hl lab\"><b>Appendicitis</b></mark> , <mark class=\"hl lab\"><b>DKA</b></mark> , Hepatitis!</li>\n</ul><h3><b>3. Stepwise Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Dietary/Lifestyle:</b> Small frequent bland/dry meals (crackers before getting out of bed), ginger, avoid fatty/spicy triggers.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>First-Line Antiemetics (SAFE in 1st Trimester!):</b> <b>Vitamin B6 (Pyridoxine 10–25 mg TID) + Doxylamine (10–25 mg)</b>!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Second-Line (If Persistent):</b> <b>Metoclopramide</b>, <b>Promethazine</b>, or <b>Ondansetron</b> (effective in refractory HG).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Hospitalization (If Ketonuria / Unable to Keep Fluids Down):</b> <b>NPO</b> briefly -&gt; <b>IV Crystalloids (0.9% Normal Saline + KCl)</b> + <b>MANDATORY IV THIAMINE (Vitamin B1 — 100 mg) BEFORE IV DEXTROSE</b> (prevents fatal <b>Wernicke Encephalopathy</b> in prolonged starvation!) -&gt; resume oral diet gradually!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u172\">← Case 1</button><button class=\"nv\" data-u=\"u174\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u174\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Ectopic Pregnancy (#1 CAUSE OF 1ST-TRIMESTER MATERNAL MORTALITY!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ectopic+Pregnancy+%28%231+CAUSE+OF+1ST-TRIMESTER+MATERNAL+MORTALITY%21%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Implantation of a fertilized blastocyst <b>OUTSIDE the uterine endometrial cavity</b> (<b>&gt; 95% in the Fallopian Tube — Ampulla [#1] &gt; Isthmus &gt; Fimbria &gt; Interstitial/Cornual [most dangerous bleed!]</b>).</p><h3><b>2. Etiology &amp; Risk Factors (Separated — Anything Damaging Tubal Motility!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Prior Pelvic Inflammatory Disease (PID — </b><i><b>Chlamydia/Gonorrhea</b></i><b>) (#1 Risk Factor!)</b> -&gt; tubal scarring!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Prior Ectopic Pregnancy</b></mark> or <b>Prior Tubal Surgery / Ligation</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Current IUD</b> (Intrauterine Device — reduces overall pregnancy, <i>but if pregnancy occurs with IUD in place, high risk it is ectopic!</i>).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Smoking</b>, <b>ART / IVF</b> (Assisted Reproductive Technology — risk of <b>Heterotopic Pregnancy</b>: simultaneous intrauterine + ectopic pregnancy!).</span></p><h3><b>3. Clinical Picture (MUST SUSPECT IN EVERY REPRODUCTIVE-AGE FEMALE WITH ABDOMINAL PAIN OR BLEEDING!)</b></h3><ul>\n<li class=\"l1\"><b>Classic Triad:</b> <b>(1) Amenorrhea (6–8 weeks)</b> + <b>(2) Lower Abdominal / Pelvic Pain</b> + <b>(3) Vaginal Bleeding (spotting)</b>!</li>\n<li class=\"l1\"><b>Ruptured Ectopic (SURGICAL EMERGENCY!):</b> Sudden agonizing pelvic pain, <b>referred Shoulder-Tip Pain</b> (hemoperitoneum irritating diaphragm via phrenic nerve!), <b>dizziness/syncope</b>, <b>hypovolemic shock</b> (tachycardia, hypotension), <b>cervical motion tenderness</b>, peritoneal rigidity!</li>\n</ul><h3><b>4. Investigations (Discriminatory Zone &amp; TVUS!)</b></h3><ul>\n<li class=\"l1\"><b>FIRST TEST:</b> <mark class=\"hl mech\"><b>Quantitative Serum β-hCG + Pelvic/Transvaginal Ultrasound (TVUS)!</b></mark></li>\n<li class=\"l2\"><b>TVUS Findings:</b> Empty uterus + complex adnexal mass (or extrauterine gestational sac with fetal pole) + <b>\"Ring of Fire\"</b> (hypervascular Doppler ring around tubal sac) + <b>free fluid in Pouch of Douglas (hemoperitoneum)</b>!</li>\n<li class=\"l2\"><b>Discriminatory Zone (~1,500–3,500 mIU/mL):</b> If β-hCG is above this threshold and TVUS shows <b>NO intrauterine gestational sac</b>, Ectopic Pregnancy is highly likely!</li>\n<li class=\"l2\"><i>If β-hCG &lt; Discriminatory Zone &amp; Patient Is Stable:</i> Repeat <mark class=\"hl mech\"><b>Serial Serum β-hCG in 48 Hours</b></mark> -&gt; Normal intrauterine pregnancy rises by <b>≥ 35–53% (typically doubles)</b> in 48 hrs; plateauing/slowly rising β-hCG = <mark class=\"hl lab\"><b>Ectopic</b></mark> (or failing pregnancy)!</li>\n</ul><h3><b>5. Treatment</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>UNSTABLE / Ruptured / Hemoperitoneum / Pain:</b> <b>IMMEDIATE Resuscitation (2 Large-Bore IVs, Cross-Match Blood) -&gt; EMERGENT LAPAROSCOPY (Salpingectomy or Salpingostomy)</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl mech\"><b>STABLE, Unruptured Ectopic (Strict Criteria: Hemodynamically stable, NO fetal cardiac activity, Sac &lt; 3.5–4 cm, β-hCG &lt; 5,000, normal LFTs/RFTs/CBC, reliable follow-up):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Single-Dose IM Methotrexate (50 mg/m²)</b></mark> -&gt; Check β-hCG on <b>Day 4 &amp; Day 7</b> (must drop <b>≥ 15% between Days 4 &amp; 7</b>; follow weekly until zero!). <i>Warn patient: avoid alcohol, folate vitamins, NSAIDs, and intercourse until resolved!</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>MANDATORY IN ALL Rh-NEGATIVE MOTHERS:</b></mark> Give <b>Anti-D Immunoglobulin (RhoGAM)</b>!</span></p>\n<p>[Image Reference Suggestion]: <b>Transvaginal Ultrasound (TVUS)</b> demonstrating an <b>Empty Uterus + Adnexal Ectopic Gestational Sac with Doppler \"Ring of Fire\"</b>.</p><nav class=\"un\"><button class=\"nv\" data-u=\"u173\">← Case 2</button><button class=\"nv\" data-u=\"u175\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u175\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Spontaneous Abortion (MISCARRIAGE — 6 CLINICAL TYPES)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Spontaneous+Abortion+%28MISCARRIAGE+%E2%80%94+6+CLINICAL+TYPES%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology (Separated)</b></h3><p>Spontaneous loss of pregnancy <b>before 20 weeks gestation</b> (or fetal weight &lt; 500 g).</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Chromosomal Abnormalities (~50–60% — #1 Cause of 1st-Trimester Loss!):</b> Trisomy 16 (#1), Monosomy X (45,XO), Triploidy.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Maternal / Uterine / Endocrine (Especially Recurrent Miscarriage ≥ 2–3 Losses!):</b> <mark class=\"hl lab\"><b>APS</b></mark> (Antiphospholipid Syndrome — treat with <mark class=\"hl rx\"><b>Aspirin + LMWH</b></mark> !), <b>Uterine Septum / Submucosal Fibroids / Asherman’s</b>, <b>Cervical Insufficiency</b> (painless 2nd-trimester dilation -&gt; <b>Cerclage</b>!), Uncontrolled DM, Hypothyroidism, Infection, Smoking.</span></p><h3><b>2. Crucial Clinical Classification (Exam Finds Cervix + Ultrasound!)</b></h3><table class=\"t wide\"><tr class=\"hd\"><th><p><b>Type</b></p></th><th><p><b>Bleeding / Pain</b></p></th><th><p><b>Cervical Os</b></p></th><th><p><b>Ultrasound / Tissue Passed</b></p></th><th><p><b>Management</b></p></th></tr><tr><td><p><b>Threatened</b></p></td><td><p>Mild bleeding +/- cramps</p></td><td><p><b>CLOSED</b></p></td><td><p><b>Live intrauterine fetus</b> (cardiac activity +)</p></td><td><p><b>Reassurance + Pelvic Rest</b> (good prognosis if heartbeat seen!)</p></td></tr><tr><td><p><b>Inevitable</b></p></td><td><p>Moderate-heavy bleeding + cramps</p></td><td><p><b>OPEN</b></p></td><td><p>Products still inside uterus (no tissue passed yet)</p></td><td><p><mark class=\"hl rx\"><b>Expectant, Medical (Misoprostol), or Surgical (Suction D&amp;C)</b></mark></p></td></tr><tr><td><p><b>Incomplete</b></p></td><td><p>Heavy bleeding + severe cramps</p></td><td><p><b>OPEN</b></p></td><td><p><b>Partial</b> tissue passed; <b>retained products</b> in uterus!</p></td><td><p><mark class=\"hl rx\"><b>Suction Evacuation (D&amp;C) or Misoprostol</b></mark> (urgent if heavy bleeding!)</p></td></tr><tr><td><p><b>Complete</b></p></td><td><p>Bleeding/pain <b>subsided</b></p></td><td><p><b>CLOSED</b></p></td><td><p><mark class=\"hl lab\"><b>ALL products passed</b></mark> ; <b>EMPTY uterus</b> on US!</p></td><td><p>Reassurance + follow β-hCG to zero</p></td></tr><tr><td><p><b>Missed</b></p></td><td><p><b>NO bleeding / NO pain </b>(asymptomatic!)</p></td><td><p><b>CLOSED</b></p></td><td><p>Dead fetus / empty gestational sac (<b>retained &gt; weeks -&gt; DIC risk!</b>)</p></td><td><p>Expectant, <mark class=\"hl rx\"><b>Misoprostol</b></mark> (+ Mifepristone), or <b>Suction D&amp;C</b></p></td></tr><tr><td><p><mark class=\"hl lab\"><b>Septic</b></mark> <i>(EMERGENCY!)</i></p></td><td><p>Fever, foul-smelling discharge, <b>tender uterus</b></p></td><td><p><b>OPEN</b></p></td><td><p>Retained infected tissue (often post-unsafe instrumentation!)</p></td><td><p><b>Immediate IV Broad-Spectrum Antibiotics</b> (Ampicillin + Gentamicin + Clindamycin) <b>+ URGENT Suction D&amp;C</b>!</p></td></tr></table><ul>\n<li class=\"l1\"><b>ALWAYS check Rh status and give Anti-D (RhoGAM)</b> to Rh-negative mothers!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u174\">← Case 3</button><button class=\"nv\" data-u=\"u176\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u176\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Gestational Trophoblastic Disease (HYDATIDIFORM MOLE)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gestational+Trophoblastic+Disease+%28HYDATIDIFORM+MOLE%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Crucial Comparison (Complete vs. Partial Mole)</b></h3><p>Abnormal proliferation of placental trophoblastic tissue!</p><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><mark class=\"hl rx\"><b>Complete Hydatidiform Mole </b></mark><i><b>(20% Risk of Cancer/GTN!)</b></i></p></th><th><p><mark class=\"hl rx\"><b>Partial Hydatidiform Mole </b></mark><i><b>(&lt; 5% Risk of GTN!)</b></i></p></th></tr><tr><td><p><b>Karyotype &amp; Origin</b></p></td><td><p><mark class=\"hl lab\"><b>46,XX (or 46,XY) — ALL PATERNAL!</b></mark> (Empty egg fertilized by 1 sperm that duplicates!)</p></td><td><p><b>69,XXX or 69,XXY (Triploid!)</b> (Normal egg fertilized by <b>2 sperm</b>!)</p></td></tr><tr><td><p><b>Fetus / Embryo?</b></p></td><td><p><b>NONE</b> (No fetal tissue or amnion!)</p></td><td><p><b>YES</b> (Abnormal non-viable fetus present!)</p></td></tr><tr><td><p><b>Clinical &amp; Ultrasound</b></p></td><td><p><mark class=\"hl dx\"><b>1st-Trimester bleeding + Passage of \"GRAPE-LIKE VESICLES\"</b></mark> , <b>Uterus LARGER than dates</b>, <mark class=\"hl mech\"><b>Sky-high β-hCG (&gt; 100,000)</b></mark> , <b>Severe Hyperemesis</b>, <mark class=\"hl lab\"><b>Early Preeclampsia (&lt; 20 wks!)</b></mark> , <b>Theca Lutein Ovarian Cysts</b>, <mark class=\"hl lab\"><b>Hyperthyroidism</b></mark> ! <b>US: \"SNOWSTORM\" (Swiss-cheese) pattern!</b></p></td><td><p>Mimics missed/incomplete abortion; uterus normal/smaller than dates; fetus visible with focal cystic placenta!</p></td></tr></table><h3><b>2. Management (DO NOT FORGET FOLLOW-UP — RULE OUT CHORIOCARCINOMA!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Baseline Labs:</b> Quantitative <mark class=\"hl mech\"><b>Serum β-hCG</b></mark> , <mark class=\"hl mech\"><b>CBC, Blood Group/Rh</b></mark> , <mark class=\"hl mech\"><b>LFTs/RFTs, TSH</b></mark> , <b>Chest X-Ray</b> (lungs = #1 site of Choriocarcinoma metastasis!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Immediate Evacuation:</b> <b>Suction Curettage (D&amp;C)</b> under ultrasound guidance (give Oxytocin <i>after</i> starting suction; avoid hysterotomy/prostaglandins!). Give <b>RhoGAM</b> if Rh-negative!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl mech\"><b>MANDATORY POST-EVACUATION SURVEILLANCE:</b></mark></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl mech\"><b>Weekly Serum β-hCG</b></mark> until undetectable (&lt; 5) for 3 consecutive weeks -&gt; then <b>monthly for 6 months</b>!</li>\n<li class=\"l2\"><b>Strict Reliable Contraception (COCs)</b> during surveillance (so a new pregnancy doesn’t confuse rising β-hCG!).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>If β-hCG Plateaus or Rises (GTN / Invasive Mole / Choriocarcinoma):</b></mark> Stage with CT Chest/Abdomen/Brain -&gt; <mark class=\"hl rx\"><b>Methotrexate</b></mark> (single-agent if low-risk) or <b>EMA-CO</b> chemotherapy (&gt; 95–99% curative!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u175\">← Case 4</button><button class=\"nv\" data-u=\"u177\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u177\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Placenta Previa &amp; Vasa Previa (PAINLESS 3RD-TRIMESTER BLEEDING!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Placenta+Previa+%26+Vasa+Previa+%28PAINLESS+3RD-TRIMESTER+BLEEDING%21%29\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Placenta Previa:</b></mark> Placenta implants <b>OVER or within &lt; 2 cm of the Internal Cervical Os</b> (Risk factors: <b>Prior Cesarean Sections</b> [#1 — especially risks <b>Placenta Accreta Spectrum!</b>], Multiparity, Prior uterine surgery/D&amp;C, Smoking, Advanced maternal age, Twins!).</li>\n<li class=\"l1\"><b>Vasa Previa:</b> Unprotected fetal umbilical vessels run across the membranes <b>overlying the internal os</b> (velamentous cord insertion / succenturiate lobe)!</li>\n</ul><h3><b>2. Clinical Picture &amp; THE GOLDEN OBSTETRIC RULE!</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Placenta Previa:</b></mark> <mark class=\"hl dx\"><b>PAINLESS, BRIGHT RED VAGINAL BLEEDING</b></mark> in the <b>2nd/3rd Trimester (&gt; 20–28 weeks)</b>, <mark class=\"hl lab\"><b>SOFT NON-TENDER UTERUS</b></mark> , normal fetal heart rate (<b>NO fetal distress initially!</b>).</li>\n<li class=\"l1\"><b>Vasa Previa:</b> Sudden <mark class=\"hl rx\"><b>painless bleeding IMMEDIATELY UPON RUPTURE OF MEMBRANES</b></mark> accompanied by <mark class=\"hl lab\"><b>RAPID FETAL BRADYCARDIA / SINUSOIDAL CTG </b></mark>(fetal exsanguination — <b>EMERGENT CESAREAN WITHIN MINUTES!</b>).</li>\n<li class=\"l1\"><b>THE GOLDEN RULE:</b> <b>NEVER, EVER PERFORM A DIGITAL VAGINAL EXAM IN A PREGNANT WOMAN WITH 2ND/3RD-TRIMESTER VAGINAL BLEEDING UNTIL PLACENTA PREVIA IS EXCLUDED BY ULTRASOUND!</b> (Digital exam causes catastrophic fatal hemorrhage!).</li>\n</ul><h3><b>3. Diagnosis &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis:</b> <b>Transabdominal -&gt; Transvaginal Ultrasound</b> (safe &amp; Gold Standard to measure distance to internal os; check for <b>Placenta Accreta</b> if prior C-section!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Management of Placenta Previa:</b></mark></li>\n<li class=\"l2\"><i>Preterm (&lt; 34–36 wks) &amp; Hemodynamically Stable:</i> Admit/expectant care, <b>Pelvic rest (no intercourse/exams!)</b>, <mark class=\"hl rx\"><b>Betamethasone</b></mark> (if 24–34 wks for fetal lung maturity), <b>RhoGAM</b> if Rh(-), correct anemia!</li>\n<li class=\"l2\"><i>Active Heavy Bleeding / Maternal-Fetal Instability OR Reached </i><i><b>36–37 Weeks</b></i><i>:</i> <b>CESAREAN DELIVERY</b>! <i>(If Placenta Accreta confirmed -&gt; planned </i><i><b>Cesarean Hysterectomy at 34–35 wks</b></i><i> without attempting to peel placenta off!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u176\">← Case 5</button><button class=\"nv\" data-u=\"u178\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u178\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Placental Abruption &amp; Uterine Rupture (PAINFUL BLEEDING!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Placental+Abruption+%26+Uterine+Rupture+%28PAINFUL+BLEEDING%21%29\">🔍 Search on Google</a></header><h3><b>A. Placental Abruption (</b><b>Abruptio Placentae</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Premature separation of a normally implanted placenta <b>BEFORE fetal delivery</b> (&gt; 20 weeks).</li>\n<li class=\"l1\"><b>Etiology / Risk Factors (Separated):</b> <mark class=\"hl lab\"><b>Chronic Hypertension / Preeclampsia (#1 Overall!)</b></mark> , <b>Abdominal Trauma (MVC/domestic assault — #1 cause of fetal death in maternal trauma!)</b>, <b>Cocaine / Smoking</b>, <b>Sudden uterine decompression</b> (rupture of polyhydramnios / delivery of 1st twin!), <b>Prior Abruption</b>, <b>PROM</b>.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> <b>PAINFUL, DARK RED VAGINAL BLEEDING</b> (~20% have <i>concealed</i> retroplacental hemorrhage with <b>NO visible bleeding</b> yet severe shock!), <b>SEVERE CONSTANT ABDOMINAL/BACK PAIN</b>, <mark class=\"hl lab\"><b>RIGID \"BOARD-LIKE / WOODEN\" TENDER UTERUS</b></mark> , <b>High-Frequency Tachysystole</b>, and <b>Acute Fetal Distress (Late Decelerations / Bradycardia)</b>!</li>\n<li class=\"l1\"><b>Complications:</b> <b>Hemorrhagic Shock</b>, <b>DIC</b> (Disseminated Intravascular Coagulation — abruption is the <b>#1 obstetric cause of DIC!</b> Check Fibrinogen, PT/aPTT, Platelets!), <b>Couvelaire Uterus</b> (blood infiltrating myometrium -&gt; PPH!).</li>\n<li class=\"l1\"><b>Treatment:</b> <mark class=\"hl rx\"><b>2 Large-Bore IVs, Type &amp; Cross-match Blood, Correct DIC (FFP/Cryoprecipitate/Platelets)!</b></mark></li>\n<li class=\"l2\"><i>Unstable Mother OR Fetal Distress:</i> <b>IMMEDIATE CESAREAN DELIVERY!</b></li>\n<li class=\"l2\"><i>Fetus Already Dead (IUFD) &amp; Mother Stable:</i> Prefer <b>Vaginal Delivery</b> (avoid surgical risk during DIC) while aggressively correcting coagulopathy! <i>(Ultrasound misses ~50% of abruptions — Diagnosis is </i><i><b>CLINICAL</b></i><i>!)</i></li>\n</ul><h3><b>B. Uterine Rupture (CATASTROPHIC EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>#1 Risk Factor:</b> <b>TOLAC / VBAC (Trial of Labor After Prior Classical/T-shaped or Low-Transverse Cesarean Section)</b>, Grand multiparity, Excessive Oxytocin.</li>\n<li class=\"l1\"><b>Classic Signs During Labor:</b> Sudden <b>tearing abdominal pain</b>, <b>SUDDEN PROFOUND FETAL BRADYCARDIA</b> (#1 earliest sign!), <b>Loss of Fetal Station</b> (presenting part moves UP out of pelvis!), <b>easily palpable fetal parts directly beneath abdominal skin</b>, <b>cessation of contractions</b>, maternal shock!</li>\n<li class=\"l1\"><b>Action:</b> <b>STAT LAPAROTOMY + EMERGENT DELIVERY</b> &amp; uterine repair/hysterectomy!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u177\">← Case 6</button><button class=\"nv\" data-u=\"u179\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u179\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Hypertensive Disorders of Pregnancy (PREECLAMPSIA, ECLAMPSIA &amp; HELLP)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertensive+Disorders+of+Pregnancy+%28PREECLAMPSIA%2C+ECLAMPSIA+%26+HELLP%29\">🔍 Search on Google</a></header><h3><b>1. Definitions (BP ≥ 140/90 mmHg on 2 occasions ≥ 4 hrs apart!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Chronic Hypertension:</b> HTN <b>before pregnancy</b> OR <b>&lt; 20 weeks gestation</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Gestational Hypertension:</b> New HTN <b>≥ 20 weeks</b> <b>WITHOUT proteinuria or severe features</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Preeclampsia:</b></mark> New HTN <b>≥ 20 weeks</b> <b>PLUS Proteinuria</b> (<b>≥ 300 mg/24 hr</b> OR <b>Urine Protein/Creatinine Ratio ≥ 0.3</b>) <b>OR ANY Severe Feature (even WITHOUT proteinuria!)</b>:</span></p>\n<ul>\n<li class=\"l2\"><b>Severe Features:</b> <b>BP ≥ 160/110 mmHg</b>, <b>Platelets &lt; 100,000</b>, <mark class=\"hl mech\"><b>AST/ALT ≥ 2× ULN + Severe RUQ/Epigastric Pain</b></mark> , <b>Serum Creatinine &gt; 1.1 mg/dL</b> (or doubled!), <b>Pulmonary Edema</b>, <b>New-Onset Unexplained Headache or Visual Disturbances (scotomata/blurring)</b>!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><mark class=\"hl lab\"><b>HELLP Syndrome:</b></mark> Severe variant — <b>H</b>emolysis (schistocytes, ↑ LDH/indirect bilirubin), <b>E</b>levated <b>L</b>iver enzymes, <b>L</b>ow <b>P</b>latelets (&lt; 100,000)!</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Eclampsia:</b></mark> New-onset <b>Generalized Tonic-Clonic Seizures</b> in a woman with preeclampsia (can occur <b>before, during, or up to 6 weeks POSTPARTUM!</b>).</span></p><h3><b>2. Pathophysiology &amp; Prevention</b></h3><p>Abnormal spiral artery remodeling in early placenta -&gt; placental ischemia -&gt; release of anti-angiogenic factors (<b>sFlt-1</b>) causing systemic <b>maternal endothelial dysfunction &amp; vasospasm</b>!</p>\n<ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Prevention in High-Risk Women (Prior Preeclampsia, Twins, Chronic HTN, DM, CKD, SLE/APS):</b></mark> <mark class=\"hl rx\"><b>Low-Dose Aspirin (81–150 mg/day)</b></mark> started at <b>12–16 weeks</b> until delivery!</li>\n</ul><h3><b>3. Treatment (DEFINITIVE CURE = DELIVERY OF FETUS &amp; PLACENTA!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Severe Acute Hypertension (BP ≥ 160/110 mmHg -&gt; Risk of Maternal Stroke!):</b> Treat within 30–60 min with <mark class=\"hl rx\"><b>IV Labetalol</b></mark> , <mark class=\"hl rx\"><b>IV Hydralazine</b></mark> , OR <b>Oral Immediate-Release Nifedipine</b> (target 140–150 / 90–100 mmHg; <i>for chronic maintenance in pregnancy: Oral Labetalol, Nifedipine XL, or Methyldopa — NEVER ACE-i/ARBs!</i>).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Seizure Prophylaxis &amp; Eclampsia Treatment (DRUG OF CHOICE = IV MAGNESIUM SULFATE [MgSO4]!):</b></mark></span></p>\n<ul>\n<li class=\"l2\">Give in <mark class=\"hl lab\"><b>ALL Eclampsia</b></mark> AND <mark class=\"hl lab\"><b>ALL Preeclampsia with Severe Features</b></mark> !</li>\n<li class=\"l2\"><b>Regimen:</b> <b>4–6 g IV Loading Dose over 15–20 min</b>, followed by <b>1–2 g/hr continuous IV infusion</b> (continue <b>24 hours POSTPARTUM</b>!).</li>\n<li class=\"l2\"><b>MONITOR FOR MgSO4 TOXICITY EVERY HOUR:</b> Check <b>(1) Deep Tendon (Patellar) Reflexes</b> (disappear FIRST at ~8–10 mEq/L!), <b>(2) Respiratory Rate ≥ 12/min </b>(respiratory depression at &gt; 12!), <b>(3) Urine Output ≥ 30 mL/hr</b> (Mg is renally excreted!).</li>\n<li class=\"l2\"><b>ANTIDOTE FOR MgSO4 TOXICITY:</b> Stop infusion + <mark class=\"hl rx\"><b>IV Calcium Gluconate 10% (1 g over 3–5 min)</b></mark> !</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Timing of Delivery:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Without Severe Features:</i> Deliver at <b>37 weeks</b>.</li>\n<li class=\"l2\"><i>With Severe Features / HELLP / Eclampsia:</i> Stabilize mother (BP + MgSO4) -&gt; <b>Deliver at ≥ 34 weeks</b> (or <b>IMMEDIATELY at ANY gestational age</b> if Eclampsia, Pulmonary Edema, DIC, Abruption, Uncontrolled BP, or Non-reassuring fetus!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u178\">← Case 7</button><button class=\"nv\" data-u=\"u180\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u180\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Gestational Diabetes Mellitus (GDM)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Gestational+Diabetes+Mellitus+%28GDM%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Pathophysiology</b></h3><p>Carbohydrate intolerance first recognized during pregnancy (<b>usually 2nd/3rd trimester</b>), driven by <b>Human Placental Lactogen (hPL)</b>, Progesterone, and Cortisol inducing marked maternal <b>insulin resistance</b>.</p><h3><b>2. Screening (24 – 28 Weeks Gestation — Earlier at 1st Visit if Obese/High-Risk!)</b></h3><ul>\n<li class=\"l1\"><b>2-Step Approach:</b> 50-g non-fasting GCT (if ≥ 130–140 mg/dL) -&gt; <b>3-Hour 100-g OGTT</b>.</li>\n<li class=\"l1\"><b>1-Step Approach (WHO/IADPSG):</b> <b>2-Hour 75-g OGTT</b> (Fasting ≥ 92, 1-hr ≥ 180, or 2-hr ≥ 153 mg/dL).</li>\n</ul><h3><b>3. Fetal &amp; Neonatal Complications (Separated!)</b></h3><ul>\n<li class=\"l1\"><i>Pre-Existing DM (1st-Trimester Hyperglycemia):</i> <b>Congenital Malformations</b> (<b>Sacral Agenesis / Caudal Regression Syndrome</b> [most specific!], <mark class=\"hl lab\"><b>VSD/ASD</b></mark> [#1 overall!], Neural Tube Defects).</li>\n<li class=\"l1\"><i>GDM (2nd/3rd-Trimester Hyperglycemia -&gt; Fetal Hyperinsulinemia!):</i> <b>Macrosomia (&gt; 4,000–4,500 g -&gt; Shoulder Dystocia!)</b>, <b>Polyhydramnios</b>, <b>Stillbirth</b>, <b>Neonatal Hypoglycemia</b> (baby’s hyperinsulinemia crashes glucose after cord cut!), <mark class=\"hl lab\"><b>Neonatal RDS</b></mark> (insulin antagonizes surfactant!), Polycythemia, Hypocalcemia!</li>\n</ul>\n<p><b>4. Treatment (Strict Glucose Targets: Fasting &lt; 95 | 1-hr Postprandial &lt; 140 | 2-hr Postprandial &lt; 120 mg/dL!)</b></p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>First-Line (~70–80% Controlled!):</b> Medical Nutrition Therapy + Moderate Exercise + 4×/day self-monitoring!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Pharmacotherapy (If Lifestyle Fails Within 1–2 Weeks):</b> <b>INSULIN is Gold Standard</b> (does NOT cross placenta!). <i>(Metformin/Glyburide cross placenta — 2nd-line if patient declines/cannot use insulin).</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Postpartum:</b> Screen with <b>75-g OGTT at 4–12 weeks postpartum</b> (50% risk of developing <b>Type 2 DM</b> within 10 years!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u179\">← Case 8</button><button class=\"nv\" data-u=\"u181\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u181\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>RH Isoimmunization &amp; Anti-D (RHOGAM) Prophylaxis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=RH+Isoimmunization+%26+Anti-D+%28RHOGAM%29+Prophylaxis\">🔍 Search on Google</a></header><h3><b>1. Pathophysiology</b></h3><p>An <b>Rh-negative mother</b> exposed to <b>Rh-positive fetal RBCs</b> develops maternal <b>Anti-D IgG antibodies</b> (which cross the placenta in <i>subsequent</i> Rh+ pregnancies!) -&gt; fatal <b>Fetal Hemolytic Anemia -&gt; High-Output Heart Failure -&gt; Hydrops Fetalis</b>!</p><h3><b>2. Prevention (MANDATORY ANTI-D IMMUNOGLOBULIN [RhoGAM 300 mcg IM] PROTOCOL!)</b></h3><p>Give <b>RhoGAM</b> to <b>EVERY Unsenzitized (Indirect Coombs Negative) Rh-Negative Mother</b> at:</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Routine Antenatal:</b> <b>28 Weeks Gestation</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Postpartum:</b> Within <b>72 Hours of Delivery</b> if newborn is <b>Rh-Positive</b> (perform <b>Kleihauer-Betke Test</b> to check if larger fetomaternal hemorrhage requires extra RhoGAM!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>After ANY Sensitizing Event:</b> <mark class=\"hl lab\"><b>Miscarriage, Ectopic Pregnancy, Molar Evacuation, CVS/Amniocentesis, Abdominal Trauma, External Cephalic Version, or Antepartum Bleeding</b></mark> !</span></p><h3><b>3. Management If Already Sensitized (Positive Indirect Coombs / Anti-D Titer ≥ 1:16)</b></h3><ul>\n<li class=\"l1\">Monitor fetal anemia non-invasively with <mark class=\"hl mech\"><b>Middle Cerebral Artery Peak Systolic Velocity (MCA-PSV) Doppler Ultrasound</b></mark> (&gt; 1.5 MoM indicates moderate-severe fetal anemia -&gt; <b>Percutaneous Umbilical Cord Blood Sampling + Intrauterine Fetal Blood Transfusion</b>!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u180\">← Case 9</button><button class=\"nv\" data-u=\"u182\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u182\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Preterm Labor (PTL) &amp; Preterm Premature Rupture of Membranes (PPROM)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Preterm+Labor+%28PTL%29+%26+Preterm+Premature+Rupture+of+Membranes+%28PPROM%29\">🔍 Search on Google</a></header><h3><b>A. Preterm Labor (PTL: Regular uterine contractions + Cervical change between 20+0 and 36+6 Weeks)</b></h3><ul>\n<li class=\"l1\"><b>Evaluation:</b> Sterile speculum exam (check fluid/bleed), Vaginal/Urine cultures + <mark class=\"hl lab\"><b>GBS swab</b></mark> , TVUS cervical length (&lt; 25 mm) / Fetal Fibronectin (high negative predictive value!).</li>\n<li class=\"l1\"><b>4 Core Interventions If &lt; 34–37 Weeks (No Chorioamnionitis/Abruption/Distress!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Antenatal Corticosteroids (&lt; 34+0 Weeks; consider 34–36+6 if steroid-naive):</b></mark> <mark class=\"hl rx\"><b>IM Betamethasone (12 mg q24h × 2 doses)</b></mark> or Dexamethasone (6 mg q12h × 4 doses) — reduces <mark class=\"hl lab\"><b>Neonatal RDS, Intraventricular Hemorrhage, &amp; NEC</b></mark> !</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Tocolysis (ONLY for 48 Hours to Allow Steroids to Work &amp; Transfer Mother!):</b> <b>Nifedipine</b> (first-line!), <mark class=\"hl rx\"><b>Indomethacin</b></mark> (&lt; 32 wks — avoid &gt; 32 wks due to premature PDA closure!), or Terbutaline. <i>(Contraindicated in Chorioamnionitis, Abruption, Severe Preeclampsia!)</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Neuroprotection (&lt; 32 Weeks):</b> <mark class=\"hl rx\"><b>IV Magnesium Sulfate</b></mark> reduces <b>Cerebral Palsy</b>!</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><mark class=\"hl lab\"><b>GBS Prophylaxis During Active Labor:</b></mark> <b>IV Penicillin G</b> (or Ampicillin).</span></p><h3><b>B. PPROM (Membrane Rupture Before 37 Weeks &amp; Before Labor Onset)</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis (Avoid Digital Vaginal Exam — Causes Chorioamnionitis! Use STERILE SPECULUM ONLY!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Pooling</b> of amniotic fluid in posterior vaginal fornix.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Nitrazine Paper Test</b> turns <b>BLUE</b> (amniotic pH 7.1–7.3 is alkaline; false-positives with blood/semen/BV!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Ferning Test</b> (\"fern-leaf\" arborization pattern on dried slide under microscope!).</span></p>\n<ul>\n<li class=\"l1\"><b>Management (If NO Chorioamnionitis, Abruption, or Fetal Distress):</b></li>\n<li class=\"l2\"><b>≥ 34 Weeks:</b> <b>Deliver</b> (induction of labor) + GBS prophylaxis.</li>\n<li class=\"l2\"><b>&lt; 34 Weeks (Expectant Management):</b> Admit -&gt; <mark class=\"hl rx\"><b>Betamethasone</b></mark> + <mark class=\"hl rx\"><b>Latency Antibiotics (IV Ampicillin + Azithromycin/Erythromycin × 48 hrs, then PO Amoxicillin + Azithromycin × 5 days)</b></mark> -&gt; prolongs pregnancy &amp; prevents neonatal sepsis! <i>(If </i><i><b>Chorioamnionitis</b></i><i> [Maternal fever ≥ 38°C + fetal/maternal tachycardia + uterine tenderness + foul fluid] -&gt; </i><mark class=\"hl rx\"><i><b>Immediate Delivery + IV Ampicillin + Gentamicin</b></i></mark><i> !)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u181\">← Case 10</button><button class=\"nv\" data-u=\"u183\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u183\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Fetal Heart Rate Monitoring (CTG) &amp; Amniotic Fluid Disorders</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Fetal+Heart+Rate+Monitoring+%28CTG%29+%26+Amniotic+Fluid+Disorders\">🔍 Search on Google</a></header><h3><b>1. Cardiotocography (CTG) Interpretation (Baseline Normal: 110–160 bpm; Moderate Variability: 6–25 bpm!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Deceleration Pattern</b></p></th><th><p><b>Timing Relative to Uterine Contraction</b></p></th><th><p><b>Mechanism</b></p></th><th><p><b>Clinical Action</b></p></th></tr><tr><td><p><b>Early Deceleration</b></p></td><td><p>Mirrors contraction (onset, <b>nadir</b>, and end match peak of contraction)</p></td><td><p><b>Head Compression</b> (vagal reflex)</p></td><td><p><b>BENIGN (Category I)</b> — Normal labor, no action needed!</p></td></tr><tr><td><p><b>Variable Deceleration</b></p></td><td><p><b>Abrupt (\"V/W-shaped\")</b> drop, variable timing</p></td><td><p><b>Umbilical Cord Compression</b></p></td><td><p><b>Reposition mother (Left/Right lateral)</b>; check for <b>Cord Prolapse</b>; <b>Amnioinfusion</b> if recurrent!</p></td></tr><tr><td><p><b>Late Deceleration </b><i>(WORRISOME!)</i></p></td><td><p><b>Gradual</b>, onset &amp; <b>nadir occur AFTER peak of contraction</b>, slow recovery!</p></td><td><p><b>UTEROPLACENTAL INSUFFICIENCY </b>(fetal hypoxia/acidosis!)</p></td><td><p><b>Category II/III — Intrauterine Resuscitation STAT:</b> Left lateral tilt, <mark class=\"hl rx\"><b>Stop Oxytocin</b></mark> , <b>IV Fluid bolus</b>, <b>O2 mask</b> -&gt; <b>Emergent Cesarean if persistent / Absent Variability / Sinusoidal!</b></p></td></tr></table><h3><b>2. Oligohydramnios vs. Polyhydramnios (AFI [Amniotic Fluid Index] Normal: 5 – 24 cm)</b></h3><ul>\n<li class=\"l1\"><b>Oligohydramnios (AFI &lt; 5 cm or Deepest Pocket &lt; 2 cm):</b> <i>Causes:</i> <b>PROM</b>, <b>Placental Insufficiency / Post-Term (&gt; 41–42 wks) / IUGR</b>, <b>Fetal Renal Agenesis (Potter Sequence)</b> / PUV! -&gt; Risk of cord compression!</li>\n<li class=\"l1\"><b>Polyhydramnios (AFI &gt; 24–25 cm or Pocket &gt; 8 cm):</b> <i>Causes:</i> <b>Idiopathic (#1)</b>, <b>Maternal Diabetes Mellitus (fetal polyuria!)</b>, <b>Fetal GI Obstruction (Esophageal/Duodenal Atresia — impaired swallowing!)</b>, Twin-to-Twin Transfusion, Hydrops! -&gt; Risk of <b>Cord Prolapse, Abruption, &amp; PPH</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u182\">← Case 11</button><button class=\"nv\" data-u=\"u184\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u184\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Normal Labor, Shoulder Dystocia &amp; Umbilical Cord Prolapse</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Normal+Labor%2C+Shoulder+Dystocia+%26+Umbilical+Cord+Prolapse\">🔍 Search on Google</a></header><h3><b>1. Stages of Normal Labor (Overview)</b></h3><ul>\n<li class=\"l1\"><b>Stage 1:</b> Onset of regular painful contractions with cervical change -&gt; <b>10 cm Full Dilation</b> (<i>Latent phase</i> -&gt; <i>Active phase</i> ≥ 6 cm).</li>\n<li class=\"l1\"><b>Stage 2:</b> 10 cm -&gt; <b>Delivery of Baby</b> (<i>Operative Vaginal Delivery [Vacuum/Forceps]</i> or C-section if prolonged/arrested!).</li>\n<li class=\"l1\"><b>Stage 3:</b> Delivery of Baby -&gt; <b>Delivery of Placenta</b> (Active management: <mark class=\"hl rx\"><b>Oxytocin after baby’s shoulder/delivery</b></mark> + gentle cord traction prevents PPH!).</li>\n<li class=\"l1\"><b>Bishop Score</b> (&lt; 6 unfavorable cervix -&gt; ripen with <mark class=\"hl rx\"><b>Misoprostol / Dinoprostone / Foley balloon</b></mark> before Oxytocin!).</li>\n</ul><h3><b>2. Two True Delivery Room Emergencies!</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>SHOULDER DYSTOCIA (Fetal Anterior Shoulder Impacted Behind Maternal Pubic Symphysis!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Clue:</i> Head delivers then retracts tightly against perineum (<b>\"Turtle Sign\"</b>)! <i>(Risk: Macrosomia/GDM!).</i></li>\n<li class=\"l2\"><b>STEPWISE PROTOCOL (\"HELPERR\" — NEVER PULL HARD ON THE BABY’S HEAD [Brachial Plexus / Erb’s Palsy] OR PRESS ON FUNDUS!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Call for Help + Episiotomy</b> (to make room for hands — <i>does not release bony block alone!</i>).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>McRoberts Maneuver (FIRST-LINE — Solves ~40–50%!):</b> <b>Hyperflex mother’s thighs tightly onto her abdomen</b> (flattens sacral promontory!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Suprapubic Pressure (Mazzanti):</b> Assistant pushes downward &amp; laterally <b>just ABOVE pubic symphysis</b> to adduct/dislodge anterior shoulder (<i>NEVER fundal pressure!</i>).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Internal Rotational Maneuvers (Rubin II / Woods Screw)</b> or <b>Deliver Posterior Arm</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>UMBILICAL CORD PROLAPSE (Cord Palpated Below Presenting Part After Rupture of Membranes + Sudden Fetal Bradycardia!):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><b>IMMEDIATE ACTION:</b> <b>DO NOT push cord back in!</b> Examiner keeps <b>gloved hand inside vagina CONTINUOUSLY LIFTING THE FETAL HEAD UPWARD OFF THE CORD</b> (plus <b>Knee-Chest / Steep Trendelenburg position</b> + fill bladder if delayed) until <b>STAT CESAREAN DELIVERY</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u183\">← Case 12</button><button class=\"nv\" data-u=\"u185\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u185\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Postpartum Hemorrhage (PPH — &quot;THE 4 Ts&quot;)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Postpartum+Hemorrhage+%28PPH+%E2%80%94+%22THE+4+Ts%22%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Cumulative blood loss <b>≥ 1,000 mL</b> (or <b>&gt; 500 mL</b> after vaginal delivery with signs of hypovolemia) within 24 hours of delivery (<b>Primary PPH</b>) or 24 hrs–12 wks (<b>Secondary PPH</b> — retained products/endometritis!).</p><h3><b>2. Etiology (Separated — Mnemonic: \"THE 4 Ts\")</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>TONE (Uterine Atony — ~70–80%, #1 OVERALL CAUSE!):</b></mark> Soft, boggy, enlarged uterus! <i>Risks:</i> <b>Overdistended uterus (Twins, Polyhydramnios, Macrosomia)</b>, <mark class=\"hl rx\"><b>Prolonged/Augmented Labor (Oxytocin desensitization)</b></mark> , <b>Grand Multiparity</b>, <b>Chorioamnionitis</b>, Halogenated anesthetics, <b>MgSO4</b>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>TRAUMA (~15–20%):</b> <b>Cervical / Vaginal / Perineal Lacerations</b>, <b>Uterine Inversion</b> (smooth red mass protruding through vagina + sudden shock -&gt; <mark class=\"hl rx\"><b>DO NOT pull placenta off; push uterus UP immediately &amp; give Nitroglycerin/Terbutaline to relax ring!</b></mark> ), <b>Uterine Rupture</b>.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>TISSUE (~10%):</b> <b>Retained Placental Fragments / Cotyledons</b>, <b>Placenta Accreta</b>.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>THROMBIN (&lt; 1–5%):</b> <b>Coagulopathy / DIC</b> (Abruption, Amniotic Fluid Embolism, Pre-existing vWD/ITP).</span></p><h3><b>3. Stepwise Emergency Treatment (ACT SIMULTANEOUSLY!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Resuscitate:</b> Call PPH team, <b>2 large-bore IVs</b>, Rapid Crystalloids + <b>Cross-Match &amp; Transfuse 1:1:1 RBCs:FFP:Platelets</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Find &amp; Fix Cause:</b></span></p>\n<ul>\n<li class=\"l2\"><b>Perform Bimanual Uterine Massage</b> + empty bladder (Foley!) -&gt; <b>Inspect Vagina/Cervix</b> for lacerations (repair!) + <b>Inspect Placenta</b> for missing cotyledons (manual/ultrasound evacuation if retained!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Uterotonic Medications (Escalate Rapidly for Uterine Atony!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>First-Line:</b> <mark class=\"hl rx\"><b>IV Oxytocin</b></mark> (10–40 U in 1 L crystalloid infusion — <i>never rapid undiluted IV bolus!</i>).</li>\n<li class=\"l2\"><b>Second-Line:</b> <b>IM Methylergonovine (Methergine 0.2 mg)</b> (<i>CONTRAINDICATED in </i><mark class=\"hl lab\"><i><b>Hypertension / Preeclampsia</b></i></mark><i> !</i>), <b>IM Carboprost (15-methyl PGF2α 250 mcg) </b>(<i>CONTRAINDICATED in </i><mark class=\"hl lab\"><i><b>Asthma</b></i></mark><i> !</i>), and/or <mark class=\"hl rx\"><b>Misoprostol (800–1,000 mcg sublingual/rectal)</b></mark> .</li>\n<li class=\"l2\"><b>MANDATORY ADJUNCT (Within 3 Hours — WOMAN Trial!):</b> <b>IV Tranexamic Acid (TXA) 1 g over 10 min</b> (reduces PPH mortality by ~30%!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Refractory Bleeding:</b> <b>Intrauterine Balloon Tamponade (Bakri Balloon)</b> -&gt; <b>B-Lynch Compression Suture / Uterine Artery Ligation / Embolization</b> -&gt; <b>Emergency Hysterectomy</b> (life-saving last resort!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u184\">← Case 13</button><button class=\"nv\" data-u=\"u186\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u186\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Postpartum Fever, Mastitis &amp; Peripartum VTE</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Postpartum+Fever%2C+Mastitis+%26+Peripartum+VTE\">🔍 Search on Google</a></header><h3><b>1. Postpartum Fever (\"5 Ws\" — Temperature ≥ 38.0°C &gt; 24 Hrs Post-Delivery)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Endometritis (#1 Cause of Postpartum Fever — Especially After C-Section!):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Presentation:</i> Fever (Day 2–5), <b>Foul-smelling lochia</b>, <b>Marked Uterine Fundal Tenderness</b>! (Polymicrobial ascending infection).</li>\n<li class=\"l2\"><i>Treatment:</i> <mark class=\"hl rx\"><b>IV Clindamycin + IV Gentamicin</b></mark> (Gold Standard — add Ampicillin if <i>Enterococcus</i> suspected!) until afebrile 24–48 hrs!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Lactational Mastitis vs. Breast Abscess (Weeks 2–6 Postpartum):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Mastitis (S. aureus via cracked nipple):</i> Unilateral, painful, <b>wedge-shaped warm erythematous breast quadrant</b> + high fever + flu-like malaise! -&gt; <mark class=\"hl mech\"><b>KEEP BREASTFEEDING / PUMPING FREQUENTLY</b></mark> (emptying milk is crucial — milk is safe for baby!) + <b>Oral Dicloxacillin / Cephalexin</b> (or Clindamycin/TMP-SMX if MRSA)!</li>\n<li class=\"l2\"><i>Breast Abscess:</i> Fluctuant tender mass failing antibiotics -&gt; <b>Ultrasound-Guided Needle Aspiration</b> (or I&amp;D) + antibiotics! <i>(If non-lactating/treatment-refractory -&gt; Biopsy to rule out </i><i><b>Inflammatory Breast Cancer</b></i><i>!)</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>UTI / Pyelonephritis</b>, <b>Wound Infection (C-Section/Episiotomy)</b>, <b>Septic Pelvic Thrombophlebitis</b> (fever persisting despite IV Clindamycin+Gentamicin with normal exam -&gt; responds to <mark class=\"hl rx\"><b>IV Heparin</b></mark> !), and <mark class=\"hl lab\"><b>Peripartum DVT/PE</b></mark> !</span></p><h3><b>2. Peripartum VTE (Leading Direct Cause of Maternal Mortality in Developed Nations!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Suspect DVT/PE</b></mark> in any pregnant/postpartum woman with unilateral leg swelling (note: <b>Left Leg &gt; Right Leg [~85%]</b> because gravid uterus + right iliac artery compress left iliac vein!), unexplained dyspnea, or pleuritic pain!</li>\n<li class=\"l1\"><b>Diagnosis:</b> <b>Lower Limb Venous Duplex Ultrasound</b> FIRST; if negative &amp; PE suspected -&gt; <mark class=\"hl mech\"><b>CXR -&gt; V/Q Scan or Low-Dose CTPA</b></mark> (never withhold imaging due to pregnancy radiation fear!).</li>\n<li class=\"l1\"><b>Treatment:</b> <mark class=\"hl rx\"><b>Therapeutic LMWH (Enoxaparin 1 mg/kg SC q12h)</b></mark> throughout pregnancy and <b>≥ 6 weeks postpartum</b> (<mark class=\"hl rx\"><b> Warfarin &amp; DOACs are CONTRAINDICATED during pregnancy!</b></mark> — Warfarin is safe during breastfeeding!).</li>\n</ul>\n<p class=\"muted\"><i>End of Part 8A — OB/GYN Obstetrics (Cases 1–15 Complete!).</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u185\">← Case 14</button><button class=\"nv\" data-u=\"u187\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u187\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Abnormal Uterine Bleeding (AUB — PALM-COEIN)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Abnormal+Uterine+Bleeding+%28AUB+%E2%80%94+PALM-COEIN%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>AUB</b> (Abnormal Uterine Bleeding) is any departure from normal menstruation in <b>frequency</b> (normal 24–38 days), <b>duration</b> (≤ 8 days), <b>regularity</b>, or <b>volume</b> (<b>Heavy Menstrual Bleeding</b> &gt; 80 mL or interfering with quality of life), including intermenstrual bleeding.</p><h3><b>2. Etiology (Separated — FIGO \"PALM-COEIN\" Classification!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>ALWAYS RULE OUT PREGNANCY FIRST</b></mark> (Urine/Serum <mark class=\"hl mech\"><b>β-hCG</b></mark> in EVERY reproductive-age woman!)!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Structural Causes (\"PALM\" — Visible on Ultrasound/Hysteroscopy):</b></span></p>\n<ul>\n<li class=\"l2\"><b>P</b>olyp (Endometrial or Endocervical polyp).</li>\n<li class=\"l2\"><b>A</b>denomyosis (Endometrial glands inside myometrium -&gt; uniformly enlarged \"boggy\" tender uterus + severe dysmenorrhea!).</li>\n<li class=\"l2\"><b>L</b>eiomyoma (<b>Fibroids</b> — especially <b>Submucosal</b> fibroids!).</li>\n<li class=\"l2\"><b>M</b>alignancy &amp; Hyperplasia (<mark class=\"hl lab\"><b> Endometrial Carcinoma / Atypical Hyperplasia</b></mark> !).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Non-Structural Causes (\"COEIN\"):</b></span></p>\n<ul>\n<li class=\"l2\"><b>C</b>oagulopathy (<b>vWD</b> [von Willebrand Disease — suspect in adolescents with heavy bleeding since menarche!], ITP, Anticoagulants).</li>\n<li class=\"l2\"><b>O</b>vulatory Dysfunction (<b>Anovulation</b> — #1 cause in <b>adolescents [immature HPO axis]</b> and <b>perimenopausal women</b>, <mark class=\"hl lab\"><b>PCOS</b></mark> , Hypothyroidism, Hyperprolactinemia!).</li>\n<li class=\"l2\"><b>E</b>ndometrial (Local hemostatic defects, <b>Endometritis</b>).</li>\n<li class=\"l2\"><b>I</b>atrogenic (<b>Copper IUD</b>, hormonal contraceptives, Tamoxifen).</li>\n<li class=\"l2\"><b>N</b>ot yet classified (AVM, cesarean scar defect/isthmocele).</li>\n</ul><h3><b>3. Investigations</b></h3><ul>\n<li class=\"l1\"><b>Mandatory First Test:</b> <mark class=\"hl mech\"><b>Urine/Serum β-hCG</b></mark> (rule out pregnancy/ectopic/miscarriage!) + <mark class=\"hl mech\"><b>CBC</b></mark> (+ Ferritin if anemic).</li>\n<li class=\"l1\"><b>Targeted Labs:</b> <mark class=\"hl mech\"><b>TSH</b></mark> , <mark class=\"hl lab\"><b>Prolactin</b></mark> , <b>Coagulation profile</b> (<mark class=\"hl mech\"><b> PT, aPTT, vWF panel</b></mark> in adolescents/bleeding history).</li>\n<li class=\"l1\"><b>Imaging:</b> <b>Pelvic / Transvaginal Ultrasound (TVUS)</b> (+/- Saline Infusion Sonohysterography for polyps/submucosal fibroids).</li>\n<li class=\"l1\"><b>Endometrial Biopsy (Pipelle — Mandatory to Rule Out Cancer!) Indicated If:</b></li>\n<li class=\"l2\">Age <b>≥ 45 years</b> with AUB, OR</li>\n<li class=\"l2\">Age <b>&lt; 45 years</b> with <b>unopposed estrogen risk factors</b> (<mark class=\"hl lab\"><b> Obesity, PCOS, Chronic Anovulation, Tamoxifen, Lynch syndrome</b></mark> , or failed medical therapy!).</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Acute Severe Hemorrhage (Unstable):</b> Resuscitate -&gt; <b>High-dose IV Conjugated Estrogen (25 mg q4–6h)</b> OR <b>High-dose Oral Combined Pills (COCs)</b> / <b>High-dose Oral Progestin</b> + <b>IV Tranexamic Acid (TXA)</b>; emergent D&amp;C / balloon tamponade if refractory!</li>\n<li class=\"l1\"><b>Chronic Non-Structural Heavy Bleeding:</b></li>\n<li class=\"l2\"><b>LNG-IUD</b> (Levonorgestrel Intrauterine Device — e.g., Mirena: <b>MOST effective medical therapy</b>, reduces bleeding by &gt; 80–90%!).</li>\n<li class=\"l2\"><b>COCs</b> (Combined Oral Contraceptives) or <b>Cyclic Oral Progestins</b> (e.g., Medroxyprogesterone / Norethisterone — essential in anovulation to prevent endometrial cancer!).</li>\n<li class=\"l2\"><b>Non-Hormonal (Taken ONLY during menses):</b> <b>Tranexamic Acid (TXA)</b> 1–1.3 g TID × 5 days + <mark class=\"hl rx\"><b>NSAIDs</b></mark> (Mefenamic acid / Ibuprofen — reduces prostaglandins and bleeding by ~30%!).</li>\n<li class=\"l1\"><b>Structural:</b> Hysteroscopic polypectomy/myomectomy, Myomectomy, Uterine Artery Embolization, or Hysterectomy.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u186\">← Case 15</button><button class=\"nv\" data-u=\"u188\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u188\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Amenorrhea (PRIMARY &amp; SECONDARY ALGORITHM)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Amenorrhea+%28PRIMARY+%26+SECONDARY+ALGORITHM%29\">🔍 Search on Google</a></header><h3><b>1. Definitions</b></h3><ul>\n<li class=\"l1\"><b>Primary Amenorrhea:</b> Absence of menarche by <b>age 15</b> with normal secondary sexual characteristics (breasts/pubic hair), <b>OR by age 13</b> with NO secondary sexual characteristics!</li>\n<li class=\"l1\"><b>Secondary Amenorrhea:</b> Absence of menses for <b>≥ 3 months</b> (if previously regular) or <b>≥ 6 months</b> (if previously irregular).</li>\n</ul><h3><b>2. Etiology (Separated)</b></h3><ul>\n<li class=\"l1\"><b>Primary Amenorrhea Causes:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><i>Compartment I (Outflow Tract — Normal Breast + Normal FSH):</i> <b>Imperforate Hymen</b> (cyclic abdominal pain + bluish bulging membrane + hematocolpos!), <b>Müllerian Agenesis (MRKH</b> [Mayer-Rokitansky-Küster-Hauser] — <b>46,XX</b>, absent uterus/upper vagina, normal ovaries/breasts!), <b>Androgen Insensitivity Syndrome</b> (<b>46,XY</b>, absent uterus, sparse/absent pubic hair, normal breasts!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><i>Compartment II (Ovary — High FSH [Hypergonadotropic Hypogonadism]):</i> <b>Turner Syndrome (45,XO)</b> (#1 cause of primary amenorrhea! Short stature, webbed neck, shield chest, streak ovaries!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><i>Compartment III/IV (Pituitary/Hypothalamus — Low/Normal FSH):</i> Constitutional delay, <b>Kallmann Syndrome</b> (anosmia + low GnRH), Stress/anorexia/athlete triad.</span></p>\n<ul>\n<li class=\"l1\"><b>Secondary Amenorrhea Causes:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Pregnancy (#1 Overall Cause — ALWAYS RULE OUT FIRST!).</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hypothalamic / Stress (~35%):</b> Functional Hypothalamic Amenorrhea (<b>Anorexia nervosa, excessive exercise, severe stress/weight loss</b> -&gt; Low GnRH, Low FSH/LH, Low Estrogen).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Ovarian (~40%):</b> <mark class=\"hl lab\"><b>PCOS</b></mark> (normal/low FSH, high LH:FSH), <b>POI</b> (Primary Ovarian Insufficiency &lt; 40 yrs — <b>High FSH &gt; 30–40 IU/L</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Pituitary (~15%):</b> <mark class=\"hl lab\"><b>Prolactinoma</b></mark> (Galactorrhea + Amenorrhea + Headache/Bitemporal hemianopia; also drugs: Antipsychotics, Metoclopramide!), <b>Sheehan’s Syndrome</b> (failure to lactate after severe PPH!).</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Uterine Outflow (~5%):</b> <b>Asherman’s Syndrome</b> (intrauterine adhesions after aggressive <b>D&amp;C</b> or endometritis!).</span></p><h3><b>3. Diagnostic Step-by-Step Algorithm (Secondary Amenorrhea)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>FIRST TEST:</b> <mark class=\"hl mech\"><b>Urine/Serum β-hCG</b></mark> (Rule out Pregnancy!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>SECOND STEP (Initial Blood Panel):</b> <mark class=\"hl mech\"><b>TSH + Serum Prolactin + Serum FSH</b></mark> (and Estradiol):</span></p>\n<ul>\n<li class=\"l2\"><i>High Prolactin:</i> Check TSH first (hypothyroidism raises TRH -&gt; raises prolactin!) + review drugs -&gt; <mark class=\"hl mech\"><b>MRI Pituitary</b></mark> !</li>\n<li class=\"l2\"><i>High FSH (&gt; 30–40 IU/L):</i> <b>POI</b> (Premature Ovarian Failure -&gt; check Karyotype if &lt; 30 yrs &amp; autoimmune panel; give <b>Estrogen + Progestin HRT</b> until age 50!).</li>\n<li class=\"l2\"><i>Low/Normal FSH + Normal Prolactin/TSH:</i> Do <b>Progestin Challenge Test</b> (Medroxyprogesterone 10 mg × 10 days):</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Withdrawal Bleed (+) = Adequate Estrogen + Patent Uterus -&gt; Anovulation (e.g., PCOS!)</b></mark> .</li>\n<li class=\"l1\"><b>No Bleed (−):</b> Give <b>Estrogen + Progestin Challenge</b>: <i>Bleed (+)</i> = Hypothalamic/Pituitary (Low Estrogen); <i>No Bleed (−)</i> = <b>Asherman’s Syndrome</b> (confirm with Hysteroscopy!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u187\">← Case 16</button><button class=\"nv\" data-u=\"u189\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u189\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Polycystic Ovary Syndrome (PCOS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Polycystic+Ovary+Syndrome+%28PCOS%29\">🔍 Search on Google</a></header><h3><b>1. Definition (Rotterdam Criteria — Requires ≥ 2 of 3, After Excluding Mimics!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Oligo-ovulation or Anovulation</b> (oligomenorrhea &lt; 8–9 cycles/year or amenorrhea).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Clinical and/or Biochemical Hyperandrogenism</b> (Hirsutism [Ferriman-Gallwey score], severe acne, male-pattern alopecia, elevated total/free Testosterone or <b>DHEA-S</b>).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Polycystic Ovaries on Ultrasound</b> (<b>≥ 20 follicles</b> [2–9 mm] per ovary or ovarian volume ≥ 10 mL — <i>\"string of pearls\"</i> appearance).</span></p><h3><b>2. Pathophysiology &amp; Must-Exclude Mimics</b></h3><ul>\n<li class=\"l1\"><b>Pathophysiology:</b> Insulin resistance + hyperinsulinemia stimulates ovarian theca cells -&gt; excess <b>androgens</b> + elevated <b>LH:FSH ratio (&gt; 2:1)</b> -&gt; arrested follicular development -&gt; anovulation -&gt; <b>unopposed estrogen</b> (high risk of <b>Endometrial Hyperplasia/Cancer!</b>).</li>\n<li class=\"l1\"><b>Must Exclude:</b> <b>Non-Classic Congenital Adrenal Hyperplasia (21-Hydroxylase deficiency — check morning 17-Hydroxyprogesterone!)</b>, Cushing’s, Thyroid disease, Hyperprolactinemia, Androgen-secreting tumor (suspect if <b>rapidly progressive virilization</b> [deep voice, clitoromegaly] or Testosterone &gt; 150–200 ng/dL!).</li>\n</ul><h3><b>3. Clinical Picture &amp; Metabolic Screening</b></h3><ul>\n<li class=\"l1\">Irregular periods since menarche, <b>hirsutism</b>, acne, <b>obesity (~50–70%)</b>, <b>acanthosis nigricans</b>, subfertility.</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Mandatory Screening in ALL PCOS Patients:</b></mark> <b>2-Hour 75-g OGTT</b> (or HbA1c/Fasting Glucose for T2DM), <b>Fasting Lipid Profile</b>, <b>BP</b> (Metabolic syndrome/MASLD screening!).</li>\n</ul><h3><b>4. Treatment (Tailored to Patient’s Goal — Fertility vs. Non-Fertility!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Weight Loss &amp; Lifestyle (First-Line for ALL Obese PCOS!):</b></mark> Even <b>5–10% weight loss</b> often restores spontaneous ovulation!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>If NOT Seeking Pregnancy Immediately:</b></span></p>\n<ul>\n<li class=\"l2\"><b>Combined Oral Contraceptives (COCs — First-Line!):</b> Regulates cycles, <b>protects endometrium from cancer</b>, lowers ovarian androgens &amp; increases <b>SHBG </b>(improves hirsutism/acne!).</li>\n<li class=\"l2\"><b>Anti-Androgens (Add after 6 months if hirsutism persists — MUST combine with reliable contraception due to male-fetus feminization risk!): </b><mark class=\"hl rx\"><b>Spironolactone</b></mark> (50–200 mg/day) or Finasteride + topical Eflornithine/laser hair removal.</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Metformin:</b></mark> Improves insulin sensitivity / prevents T2DM (does NOT significantly improve hirsutism alone).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>If SEEKING Pregnancy (Ovulation Induction):</b></span></p>\n<ul>\n<li class=\"l2\"><b>First-Line Drug:</b> <b>Letrozole</b> (Aromatase inhibitor — <b>SUPERIOR live-birth rates and LOWER twin risk than Clomiphene!</b>) -&gt; Second-line: <b>Clomiphene Citrate</b> (+/-Metformin) -&gt; Gonadotropins / Laparoscopic ovarian drilling / <b>IVF</b>.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u188\">← Case 17</button><button class=\"nv\" data-u=\"u190\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u190\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Dysmenorrhea, Endometriosis &amp; Adenomyosis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dysmenorrhea%2C+Endometriosis+%26+Adenomyosis\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Comparison</b></h3><ul>\n<li class=\"l1\"><b>Primary Dysmenorrhea:</b> Painful menstruation <b>WITHOUT pelvic pathology</b> (starts 1–2 yrs after menarche; excess endometrial <b>PGF2α</b> [Prostaglandin F2-alpha] causing uterine ischemia). <i>Treatment:</i> <mark class=\"hl rx\"><b>NSAIDs</b></mark> (Ibuprofen/Naproxen/Mefenamic acid started at onset/just before menses!) and/or <b>COCs</b>!</li>\n<li class=\"l1\"><b>Secondary Dysmenorrhea:</b> Painful menstruation <b>WITH underlying pelvic pathology</b> (onset later in 20s–30s, worsens progressively, pain starts <i>before</i> menses!):</li>\n<li class=\"l2\"><b>Endometriosis:</b> Ectopic endometrial glands &amp; stroma <b>OUTSIDE the uterus</b> (ovaries [<b>\"Chocolate Cysts\" / Endometriomas</b>], uterosacral ligaments, Pouch of Douglas).</li>\n<li class=\"l2\"><b>Adenomyosis:</b> Ectopic endometrial glands <b>INSIDE the uterine myometrium</b>.</li>\n</ul><h3><b>2. Clinical Picture: Endometriosis vs. Adenomyosis</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Endometriosis</b></p></th><th><p><b>Adenomyosis</b></p></th></tr><tr><td><p><b>Classic Patient</b></p></td><td><p>Nulliparous woman (20s–30s)</p></td><td><p><b>Multiparous woman (35–50 yrs)</b></p></td></tr><tr><td><p><b>Key Symptoms</b></p></td><td><p>Progressive dysmenorrhea, <b>deep dyspareunia</b>, <b>dyschezia</b> (painful defecation during menses), <b>infertility</b></p></td><td><p><b>Heavy Menstrual Bleeding (Menorrhagia)</b> + severe dysmenorrhea</p></td></tr><tr><td><p><b>Pelvic Exam</b></p></td><td><p><b>Fixed, retroverted uterus</b>, <b>uterosacral ligament nodularity</b>, tender adnexal mass (endometrioma)</p></td><td><p><b>Uniformly enlarged, globular, soft/\"boggy\", tender uterus</b> (&lt; 12 wks size)</p></td></tr><tr><td><p><b>Gold Standard Diagnosis</b></p></td><td><p><b>Diagnostic Laparoscopy</b> (\"powder-burn\" implants; <i>TVUS/MRI detects endometriomas</i>)</p></td><td><p><mark class=\"hl mech\"><b>TVUS / Pelvic MRI</b></mark> (thickened junctional zone &gt; 12 mm; definitive on hysterectomy pathology)</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><mark class=\"hl rx\"><b>NSAIDs + Continuous COCs or Progestins</b></mark> (Dienogest/MPA) -&gt; <b>GnRH Agonists/Antagonists</b> (Leuprolide/Elagolix + add-back) -&gt; <mark class=\"hl rx\"><b>Laparoscopic excision/ablation</b></mark></p></td><td><p><b>LNG-IUD (Mirena — Best medical option!)</b>, COCs/TXA; <b>Definitive Cure = Hysterectomy</b>!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u189\">← Case 18</button><button class=\"nv\" data-u=\"u191\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u191\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Uterine Leiomyomas (FIBROIDS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Uterine+Leiomyomas+%28FIBROIDS%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Types</b></h3><p>Benign monoclonal smooth muscle tumors of the uterus (estrogen &amp; progesterone sensitive — <b>grow during pregnancy/reproductive years and SHRINK after menopause!</b>).</p>\n<ul>\n<li class=\"l1\"><b>Submucosal</b> (protrude into cavity -&gt; <b>#1 cause of Heavy Bleeding &amp; Infertility/Miscarriage!</b>).</li>\n<li class=\"l1\"><b>Intramural</b> (within myometrium — most common).</li>\n<li class=\"l1\"><b>Subserosal</b> (protrude outward -&gt; <b>bulk/pressure symptoms</b>: urinary frequency, constipation; <i>pedunculated torsion</i>!).</li>\n</ul><h3><b>2. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Often <b>asymptomatic</b> (~50%). Symptoms: <b>Heavy prolonged menstrual bleeding</b> (anemia), pelvic pressure/pain, urinary frequency, subfertility.</li>\n<li class=\"l1\"><i>Pregnancy Complication — \"Red Degeneration\":</i> Rapid fibroid growth outstrips blood supply -&gt; acute severe focal uterine pain + fever/leukocytosis in 2nd trimester -&gt; manage conservatively (hydration + analgesia)!</li>\n<li class=\"l1\"><b>Exam:</b> Firm, <b>irregular, lobulated, non-tender enlarged uterus</b>.</li>\n<li class=\"l1\"><b>Imaging:</b> <b>Pelvic Ultrasound (TVUS)</b> (well-circumscribed hypoechoic uterine masses) +/- Saline sonogram / MRI before surgery.</li>\n<li class=\"l1\"><i>Red Flag:</i> <b>Rapidly growing uterine mass in a POSTMENOPAUSAL woman</b> = rule out <b>Leiomyosarcoma</b>!</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Asymptomatic Fibroids:</b> <b>Observation ONLY</b> (even if large, unless obstructing ureters or suspicious!).</li>\n<li class=\"l1\"><b>Medical (Symptom Control):</b> <b>LNG-IUD</b> (if cavity not distorted), <b>COCs</b>, <b>Tranexamic Acid</b>, Oral <b>GnRH Antagonists</b> (Elagolix/Relugolix + add-back) or <b>GnRH Agonist </b>(Leuprolide — shrinks fibroids pre-op for 3–6 months!).</li>\n<li class=\"l1\"><b>Procedures / Surgery:</b></li>\n<li class=\"l2\"><i>Desires Future Fertility:</i> <b>Myomectomy</b> (Hysteroscopic for submucosal; Laparoscopic/Open for intramural/subserosal).</li>\n<li class=\"l2\"><i>Completed Childbearing:</i> <b>Uterine Artery Embolization (UAE)</b> OR <b>Hysterectomy</b> (only definitive cure!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u190\">← Case 19</button><button class=\"nv\" data-u=\"u192\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u192\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Pelvic Inflammatory Disease (PID) &amp; Tubo-Ovarian Abscess (TOA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pelvic+Inflammatory+Disease+%28PID%29+%26+Tubo-Ovarian+Abscess+%28TOA%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology (Separated)</b></h3><p>Ascending polymicrobial infection of the upper female genital tract (endometritis, salpingitis, oophoritis, pelvic peritonitis).</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Primary Sexually Transmitted Pathogens:</b> <i><b>Chlamydia trachomatis</b></i> (#1 overall!) and <i><b>Neisseria gonorrhoeae</b></i>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Secondary Polymicrobial / Anaerobic Flora:</b> <i>Gardnerella</i>, <i>Mycoplasma genitalium</i>, <i>E. coli</i>, <i>Bacteroides</i>, <i>Streptococci</i>.</span></p><h3><b>2. Clinical Picture (Low Threshold to Treat to Prevent Infertility!)</b></h3><ul>\n<li class=\"l1\">Sexually active young woman presenting with <b>lower abdominal/pelvic pain</b> + <b>≥ 1 of the Minimum Diagnostic Criteria on Bimanual Exam:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Cervical Motion Tenderness (\"Chandelier Sign\")</b>, OR</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Uterine Tenderness</b>, OR</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Adnexal Tenderness</b>.</span></p>\n<ul>\n<li class=\"l1\"><i>Supporting signs:</i> Fever &gt; 38.3°C, mucopurulent cervical discharge, elevated ESR/CRP, positive <i>Chlamydia/Gonorrhea</i> <b>NAAT</b>.</li>\n<li class=\"l1\"><b>Fitz-Hugh-Curtis Syndrome:</b> <b>RUQ pleuritic pain</b> from perihepatitis (\"violin-string\" adhesions on liver capsule — mimics cholecystitis!).</li>\n</ul><h3><b>3. Complications &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Complications:</b> <b>Tubo-Ovarian Abscess (TOA)</b> (palpable/US complex adnexal mass + high fever!), <mark class=\"hl lab\"><b>Ectopic Pregnancy</b></mark> , <b>Chronic Pelvic Pain</b>, <b>Tubal Infertility</b>.</li>\n<li class=\"l1\"><b>Treatment (MUST Cover </b><i><b>Gonorrhea + Chlamydia + Anaerobes</b></i><b>!):</b></li>\n<li class=\"l2\"><b>Outpatient (Mild-Moderate):</b> <mark class=\"hl rx\"><b>Single IM Ceftriaxone 500 mg</b></mark> (1 g if ≥ 150 kg) <mark class=\"hl rx\"><b>PLUS Oral Doxycycline 100 mg BID × 14 days PLUS Oral Metronidazole 500 mg BID × 14 days</b></mark> !</li>\n<li class=\"l2\"><b>Inpatient (Pregnancy, TOA, Severe fever/vomiting, Failed PO at 48–72 hrs):</b> <mark class=\"hl rx\"><b>IV Cefotetan/Cefoxitin + Doxycycline</b></mark> (OR <mark class=\"hl rx\"><b>IV Clindamycin + Gentamicin</b></mark> for TOA!) -&gt; Percutaneous drainage/surgery if TOA fails antibiotics or ruptures (<b>sepsis emergency!</b>). <b>Treat sexual partner(s)</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u191\">← Case 20</button><button class=\"nv\" data-u=\"u193\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u193\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Vaginitis &amp; Vaginal Discharge Differentiation</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vaginitis+%26+Vaginal+Discharge+Differentiation\">🔍 Search on Google</a></header><p class=\"muted\"><i>(Never treat all vaginal discharge blindly with antifungals — examine pH &amp; microscopy!)</i></p><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Bacterial Vaginosis (BV) </b><i><b>(#1 Overall!)</b></i></p></th><th><p><b>Vulvovaginal Candidiasis (VVC)</b></p></th><th><p><b>Trichomoniasis </b><i><b>(STI!)</b></i></p></th></tr><tr><td><p><b>Etiology</b></p></td><td><p>Overgrowth of <i>Gardnerella vaginalis</i> + anaerobes (loss of <i>Lactobacillus</i>)</p></td><td><p><i><b>Candida albicans</b></i> (triggers: antibiotics, DM, pregnancy, steroids)</p></td><td><p><i><b>Trichomonas vaginalis </b></i>(flagellated protozoan)</p></td></tr><tr><td><p><b>Discharge</b></p></td><td><p>Thin, homogeneous <b>grayish-white</b>, <b>\"fishy\" amine odor</b> (worse after intercourse/menses)</p></td><td><p>Thick, white <b>\"cottage-cheese / curdy\"</b> (NO odor)</p></td><td><p><b>Frothy, yellow-green</b>, malodorous</p></td></tr><tr><td><p><b>Symptoms</b></p></td><td><p>Odor &amp; discharge (minimal/NO inflammation or itch!)</p></td><td><p><b>Intense vulvovaginal itching (pruritus)</b>, burning, erythema, dysuria</p></td><td><p><b>Pruritus</b>, dysuria, dyspareunia, <b>\"Strawberry Cervix\"</b> (punctate hemorrhages)</p></td></tr><tr><td><p><b>Vaginal pH</b></p></td><td><p><b>&gt; 4.5</b> (Alkaline)</p></td><td><p><b>Normal (3.8 – 4.5)</b></p></td><td><p><b>&gt; 4.5</b> (Alkaline)</p></td></tr><tr><td><p><b>Microscopy</b></p></td><td><p><b>\"Clue Cells\"</b> (epithelial cells studded with bacteria) + <b>Positive \"Whiff Test\"</b> (fishy smell with KOH)</p></td><td><p><b>Budding yeast &amp; Pseudohyphae</b> on <b>KOH prep</b></p></td><td><p><b>Motile flagellated trichomonads</b> on wet mount (or NAAT)</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><mark class=\"hl rx\"><b>Oral Metronidazole 500 mg BID × 7 days</b></mark> (or topical Metronidazole/Clindamycin gel). <i>No partner treatment needed!</i></p></td><td><p><mark class=\"hl rx\"><b>Single-dose Oral Fluconazole 150 mg</b></mark> OR Topical Azole (<b>Clotrimazole/Miconazole</b>) 3–7 days <i>(Use </i><i><b>topical azoles ONLY</b></i><i> in pregnancy!)</i></p></td><td><p><mark class=\"hl rx\"><b>Oral Metronidazole 500 mg BID × 7 days</b></mark> (women) or 2 g single dose + <b>TREAT SEXUAL PARTNER!</b></p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u192\">← Case 21</button><button class=\"nv\" data-u=\"u194\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u194\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Ovarian Cysts &amp; Ovarian Torsion</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Ovarian+Cysts+%26+Ovarian+Torsion\">🔍 Search on Google</a></header><h3><b>1. Common Benign Ovarian Cysts (Premenopausal)</b></h3><ul>\n<li class=\"l1\"><b>Functional Cysts (Follicular / Corpus Luteum):</b> Most common (&lt; 5–8 cm); asymptomatic or unilateral dull ache; <b>resolve spontaneously within 2–3 menstrual cycles</b> -&gt; repeat Pelvic US in 6–12 weeks (no surgery needed unless ruptured with hemoperitoneum!).</li>\n<li class=\"l1\"><b>Dermoid Cyst (Mature Cystic Teratoma):</b> Most common neoplastic cyst in young women (contains hair/teeth/sebaceous tissue — Rokitansky nodule on US); <b>high risk of Torsion</b> -&gt; Laparoscopic <b>Cystectomy</b>!</li>\n</ul><h3><b>2. Ovarian (Adnexal) Torsion (GYNECOLOGIC SURGICAL EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Twisting of the ovary/fallopian tube on its vascular pedicle (infundibulopelvic ligament), cutting off venous then arterial blood supply!</li>\n<li class=\"l1\"><b>Clinical Picture:</b> <b>Sudden-onset severe unilateral lower abdominal/pelvic pain</b> (often after sudden movement/exercise) + <b>profound Nausea &amp; Vomiting</b> + tender unilateral adnexal mass!</li>\n<li class=\"l1\"><b>Investigations:</b> <b>Pelvic Ultrasound with Color Doppler</b> (<b>absent or decreased ovarian venous/arterial flow</b> + enlarged edematous ovary; <i>NOTE: Normal Doppler flow does NOT 100% exclude intermittent torsion — treat clinically if high suspicion!</i>); <mark class=\"hl mech\"><b>MANDATORY β-hCG</b></mark> (rule out ectopic!).</li>\n<li class=\"l1\"><b>Treatment:</b> <b>EMERGENT LAPAROSCOPY with Detorsion</b> (untwist ovary to salvage ovarian function — <b>do NOT automatically remove ovary even if bluish/ischemic </b>unless frankly necrotic!) + Cystectomy!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u193\">← Case 22</button><button class=\"nv\" data-u=\"u195\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u195\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Pelvic Organ Prolapse (POP) &amp; Female Urinary Incontinence</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pelvic+Organ+Prolapse+%28POP%29+%26+Female+Urinary+Incontinence\">🔍 Search on Google</a></header><h3><b>1. Pelvic Organ Prolapse (POP)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Herniation of pelvic organs into/beyond the vaginal walls due to weakened pelvic floor support (levator ani / uterosacral ligaments — risk factors: <b>multiparity/vaginal deliveries</b>, aging/menopause, obesity, chronic cough/constipation).</li>\n<li class=\"l1\"><b>Types:</b> <b>Cystocele</b> (anterior wall/bladder), <b>Rectocele</b> (posterior wall/rectum -&gt; needs vaginal splinting to defecate!), <b>Uterine Prolapse</b> (cervix descends toward/outside introitus).</li>\n<li class=\"l1\"><b>Treatment:</b> Pelvic floor muscle (<b>Kegel</b>) exercises, <b>Vaginal Pessary</b> (non-surgical support), or <b>Surgical Repair</b> (anterior/posterior colporrhaphy, sacrocolpopexy, vaginal hysterectomy).</li>\n</ul><h3><b>2. Female Urinary Incontinence (3 Main Types — Separate Carefully!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Type</b></p></th><th><p><b>Pathophysiology</b></p></th><th><p><b>Classic Symptom</b></p></th><th><p><b>First-Line Treatment</b></p></th></tr><tr><td><p><b>Stress Incontinence</b></p></td><td><p>Weak pelvic floor / urethral hypermobility</p></td><td><p><b>Leakage with coughing, sneezing,</b></p></td><td><p><b>Pelvic floor (Kegel) exercises</b>, weight loss,</p></td></tr><tr><td></td><td></td><td><p><b>laughing, lifting</b> (small volume)</p></td><td><p>pessary -&gt; <b>Mid-urethral Sling (TVT/TOT)</b>!</p></td></tr><tr><td><p><b>Urge Incontinence (Overactive Bladder)</b></p></td><td><p>Detrusor muscle overactivity</p></td><td><p><b>Sudden intense urge to void (\"key-in-door\" syndrome)</b> with involuntary large-volume leak + frequency/nocturia</p></td><td><p><b>Bladder training</b> + <b>Antimuscarinics (Oxybutynin, Solifenacin, Tolterodine)</b> or <b>Mirabegron</b> (β3-agonist — safer in elderly!)</p></td></tr><tr><td><p><b>Overflow Incontinence</b></p></td><td><p>Impaired detrusor contractility (DM neuropathy) or outlet obstruction</p></td><td><p>Constant dribbling + <b>high Post-Void Residual (&gt; 150–200 mL)</b></p></td><td><p>Clean intermittent catheterization, treat obstruction, Bethanechol (if atonic)</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u194\">← Case 23</button><button class=\"nv\" data-u=\"u196\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u196\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Infertility Evaluation (BASIC WORKUP)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Infertility+Evaluation+%28BASIC+WORKUP%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Failure to achieve clinical pregnancy after <b>12 months</b> of regular, unprotected intercourse (or after <b>6 months</b> if female age <b>≥ 35 years</b>!).</p><h3><b>2. Etiology (Separated — Evaluate BOTH Partners Simultaneously!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Male Factor (~30–40%):</b> Varicocele (#1 surgically correctable!), hypogonadism, obstruction, genetic (Klinefelter 47,XXY), heat/smoking/toxins.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Ovulatory Dysfunction (~25–30%):</b> <mark class=\"hl lab\"><b>PCOS</b></mark> (#1!), Hypothalamic amenorrhea, Hyperprolactinemia, Thyroid disease, Diminished Ovarian Reserve / POI.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Tubal / Peritoneal Factor (~25–30%):</b> Prior <b>PID</b>, <b>Endometriosis</b>, pelvic adhesions/prior abdominal surgery.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Uterine / Cervical / Unexplained (~10–20%):</b> Submucosal fibroids, uterine septum, Asherman’s.</span></p><h3><b>3. Essential Initial Workup (4 Core Tests)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Male Partner FIRST (Non-Invasive &amp; Cheap!):</b> <b>Semen Analysis</b> (after 2–7 days abstinence — repeat if abnormal!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Confirm Ovulation:</b> History of regular cycles, <b>Mid-Luteal (Day 21) Serum Progesterone (&gt; 3–10 ng/mL)</b>, Urine LH kits; check <mark class=\"hl mech\"><b>TSH, Prolactin</b></mark> , <b>Day 2–3 FSH/Estradiol &amp; AMH</b> (Anti-Müllerian Hormone — ovarian reserve).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Tubal Patency &amp; Uterine Cavity:</b> <b>HSG</b> (Hysterosalpingography — done follicular phase Day 7–10!) or <b>Hysteroscopy/Laparoscopy</b>.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Treatment:</b> Targeted (Letrozole for PCOS; Surgery for varicocele/septum/polyps; <b>IUI</b> [Intrauterine Insemination] for mild male/unexplained; <b>IVF / ICSI</b> for bilateral tubal blockage, severe male factor, or advanced age!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u195\">← Case 24</button><button class=\"nv\" data-u=\"u197\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u197\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Contraception Mastery (WHO MEC SAFETY RULES!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Contraception+Mastery+%28WHO+MEC+SAFETY+RULES%21%29\">🔍 Search on Google</a></header><table class=\"t \"><tr><td><p><b>Method</b></p></td><td><p><b>Mechanism</b></p></td><td><p><b>Key Benefits</b></p></td><td><p><b>ABSOLUTE CONTRAINDICATIONS (WHO Category 4 — MUST KNOW!)</b></p></td></tr><tr><td><p><b>COCs</b> <i>(Estrogen + Progestin Pills/Patch/Ring)</i></p></td><td><p>Suppresses ovulation (LH/FSH), thickens mucus</p></td><td><p>Regulates cycles, reduces dysmenorrhea, acne, <b>lowers Ovarian &amp; Endometrial cancer risk by 50%!</b></p></td><td><p><b>Age ≥ 35 + Smoking ≥ 15/day</b>, <mark class=\"hl lab\"><b>Migraine WITH Aura </b></mark>(stroke risk!), <mark class=\"hl lab\"><b>History of DVT/PE</b></mark> , <b>Uncontrolled HTN (≥ 160/100)</b>, <mark class=\"hl lab\"><b>Active Breast Cancer</b></mark> , <b>&lt; 3–6 weeks postpartum / Breastfeeding &lt; 6 wks</b>, Liver tumor/decompensated cirrhosis! <i>(Note: </i><i><b>Rifampin, Carbamazepine, Phenytoin</b></i><i> decrease COC efficacy!)</i></p></td></tr><tr><td><p><b>POPs</b> <i>(Progestin-Only \"Mini-Pill\") / </i><i><b>Etonogestrel Implant</b></i><i> / </i><i><b>DMPA Injection</b></i></p></td><td><p>Thickens cervical mucus (+/-suppresses ovulation)</p></td><td><p><mark class=\"hl lab\"><b>SAFE in Breastfeeding, Smokers ≥ 35, Migraine with Aura, HTN, &amp; DVT history!</b></mark></p></td><td><p><mark class=\"hl lab\"><b>Active Breast Cancer</b></mark> ; DMPA causes reversible <b>bone mineral density loss</b> &amp; delayed return to fertility (6–12 mos)</p></td></tr><tr><td><p><b>Copper IUD</b> <i>(Non-hormonal, lasts 10 yrs)</i></p></td><td><p>Spermicidal copper inflammatory reaction</p></td><td><p>Hormone-free, <b>most effective Emergency Contraception (&lt; 5 days)</b>!</p></td><td><p>Current <b>PID / Purulent cervicitis</b>, Pregnancy, Distorted uterine cavity, Wilson’s disease; <i>causes heavier bleeding/cramps!</i></p></td></tr><tr><td><p><b>Levonorgestrel IUD (Mirena)</b> <i>(Lasts 5–8 yrs)</i></p></td><td><p>Thickens mucus, thins endometrium</p></td><td><p><b>Dramatically reduces menorrhagia &amp; dysmenorrhea!</b></p></td><td><p>Active PID, Pregnancy, Breast cancer, Distorted cavity</p></td></tr></table><ul>\n<li class=\"l1\"><b>Emergency Contraception (Unprotected Intercourse):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Copper IUD Insertion</b> within <b>5 days (120 hrs)</b> — <b>&gt; 99% effective</b> (works regardless of BMI!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Ulipristal Acetate 30 mg</b> within <b>5 days (120 hrs)</b> — most effective pill!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Levonorgestrel 1.5 mg (Plan B)</b> within <b>3 days (72 hrs)</b> — less effective if BMI &gt; 30!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u196\">← Case 25</button><button class=\"nv\" data-u=\"u198\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u198\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Menopause, HRT &amp; Postmenopausal Bleeding (PMB)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Menopause%2C+HRT+%26+Postmenopausal+Bleeding+%28PMB%29\">🔍 Search on Google</a></header><h3><b>1. Menopause &amp; HRT (Hormone Replacement Therapy)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Retrospective clinical diagnosis after <b>12 consecutive months of amenorrhea</b> (mean age ~51 yrs; <b>NO labs needed</b> if typical age — FSH &gt; 40 confirms premature menopause &lt; 40 yrs).</li>\n<li class=\"l1\"><b>Symptoms:</b> <b>Vasomotor hot flashes &amp; night sweats</b>, <b>Genitourinary Syndrome of Menopause</b> (vaginal dryness, dyspareunia, recurrent UTIs), sleep/mood changes, accelerated <mark class=\"hl lab\"><b>Osteoporosis</b></mark> &amp; CV risk.</li>\n<li class=\"l1\"><b>HRT Rules (Lowest dose, shortest duration for moderate-severe hot flashes in women &lt; 60 yrs or &lt; 10 yrs from menopause):</b></li>\n<li class=\"l2\"><b>Intact Uterus:</b> <b>MUST give Estrogen + Progestin</b> (Progestin protects endometrium from Estrogen-induced cancer!).</li>\n<li class=\"l2\"><b>Prior Hysterectomy (No Uterus):</b> <b>Estrogen ALONE</b>!</li>\n<li class=\"l2\"><b>Isolated Vaginal Dryness / Dyspareunia ONLY:</b> <b>Topical Vaginal Estrogen Cream/Ring</b> (minimal systemic absorption!).</li>\n<li class=\"l2\"><i>Contraindications:</i> Breast cancer, CHD/Stroke, DVT/PE, undiagnosed vaginal bleeding, active liver disease. <i>(Non-hormonal options for hot flashes: </i><i><b>SSRIs/SNRIs [Venlafaxine/Paroxetine]</b></i><i>, Gabapentin, Fezolinetant).</i></li>\n</ul><h3><b>2. Postmenopausal Bleeding (PMB — HIGHEST YIELD RULE IN GYNECOLOGY!)</b></h3><ul>\n<li class=\"l1\"><b>THE GOLDEN RULE:</b> <b>ANY vaginal bleeding ≥ 12 months after menopause = ENDOMETRIAL CARCINOMA UNTIL PROVEN OTHERWISE!</b> (Even though <b>Endometrial Atrophy</b> is the #1 benign cause overall!).</li>\n<li class=\"l1\"><b>Mandatory Workup:</b> <b>TVUS</b> (measure Endometrial Stripe thickness: if <b>≤ 4 mm</b>, cancer risk is &lt; 1%; if <b>&gt; 4 mm</b> OR persistent bleeding -&gt; <b>Endometrial Biopsy / Hysteroscopy + D&amp;C</b>!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u197\">← Case 26</button><button class=\"nv\" data-u=\"u199\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u199\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Cervical Cancer Screening &amp; Cervical Carcinoma</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cervical+Cancer+Screening+%26+Cervical+Carcinoma\">🔍 Search on Google</a></header><h3><b>1. Etiology &amp; Risk Factors</b></h3><ul>\n<li class=\"l1\"><b>Primary Cause (&gt; 99%):</b> Persistent infection with <b>High-Risk HPV (Human Papillomavirus — Types 16 &amp; 18 account for ~70%!)</b>.</li>\n<li class=\"l1\"><b>Cofactors:</b> Early age at first intercourse, multiple sexual partners, <b>Smoking</b>, Immunosuppression (<b>HIV</b>).</li>\n</ul><h3><b>2. Screening Guidelines (ACOG / USPSTF — Applies to Average-Risk Women!)</b></h3><ul>\n<li class=\"l1\"><b>&lt; 21 Years:</b> <b>NO Screening!</b></li>\n<li class=\"l1\"><b>21 – 29 Years:</b> <b>Cervical Cytology (Pap Smear) alone every 3 years</b> (NO routine HPV test &lt; 25–30!).</li>\n<li class=\"l1\"><b>30 – 65 Years:</b> <b>Co-testing (Pap Smear + High-Risk HPV) every 5 years</b> (preferred) OR <b>Primary HPV testing every 5 years</b> OR <b>Pap alone every 3 years</b>.</li>\n<li class=\"l1\"><b>&gt; 65 Years:</b> <b>Stop screening</b> if adequate negative prior screening (3 consecutive negative Paps or 2 negative co-tests in past 10 yrs) and no CIN2+ history!</li>\n<li class=\"l1\"><b>Abnormal Pap Results:</b> <b>ASC-US</b> (do reflex HPV) | <b>LSIL</b> (HPV+ / &gt; 25 -&gt; Colposcopy) | <b>HSIL / ASC-H</b> -&gt; <mark class=\"hl mech\"><b>Immediate Colposcopy + Biopsy</b></mark> ! (Treat CIN 2/3 with <b>LEEP </b>[Loop Electrosurgical Excision Procedure] or Cold-Knife Conization!).</li>\n<li class=\"l1\"><b>Prevention:</b> <b>HPV Vaccine (Gardasil 9)</b> routinely at age <b>11–12 years</b> (catch-up up to 26–45 yrs).</li>\n</ul><h3><b>3. Invasive Cervical Carcinoma</b></h3><ul>\n<li class=\"l1\"><b>Clinical Picture:</b> <b>Postcoital vaginal bleeding</b> (classic!), intermenstrual bleeding, foul-smelling watery/bloody discharge, visible fungating/ulcerative cervical mass, pelvic pain, <b>hydronephrosis / ureteral obstruction</b> (late).</li>\n<li class=\"l1\"><b>Treatment:</b> Early (<b>Stage IA–IB1/2</b>) -&gt; <b>Radical Hysterectomy + Pelvic Lymphadenectomy</b> (or fertility-sparing Trachelectomy); Locally Advanced (<b>≥ IB3–IVA</b>) -&gt; <b>Concurrent Cisplatin Chemoradiation</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u198\">← Case 27</button><button class=\"nv\" data-u=\"u200\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u200\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Endometrial Carcinoma vs. Ovarian Carcinoma</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Endometrial+Carcinoma+vs.+Ovarian+Carcinoma\">🔍 Search on Google</a></header><table class=\"t \"><tr><td><p><b>Feature</b></p></td><td><p><mark class=\"hl lab\"><b>Endometrial Carcinoma </b></mark><i><b>(#1 Gyn Cancer in Developed World)</b></i></p></td><td><p><b>Ovarian Carcinoma </b><i><b>(#1 Cause of Gyn Cancer Death — \"Silent Killer\"!)</b></i></p></td></tr><tr><td><p><b>Risk Factors</b></p></td><td><p><b>Unopposed Estrogen:</b> <b>Obesity (#1!)</b>, Nulliparity, Early menarche/Late menopause, <mark class=\"hl lab\"><b>PCOS</b></mark> , DM, HTN, <b>Tamoxifen</b>, <b>Lynch Syndrome</b> <i>(Protective: COCs, Smoking, Multiparity!)</i></p></td><td><p><b>Advancing age</b>, Nulliparity, Early menarche/Late menopause, <b>BRCA1 / BRCA2 </b>mutations, Lynch syndrome <i>(Protective: </i><i><b>COCs [50% risk reduction!]</b></i><i>, Breastfeeding, Multiparity, Tubal ligation!)</i></p></td></tr><tr><td><p><b>Classic Presentation</b></p></td><td><p><b>Early Postmenopausal Bleeding (PMB)</b> -&gt; diagnosed early!</p></td><td><p><b>Late Stage (III/IV) at diagnosis:</b> Vague <b>abdominal bloating/distension (ascites!)</b>, <b>early satiety</b>, pelvic pain, urinary urgency, <b>unilateral solid/complex ovarian mass in a postmenopausal woman</b>!</p></td></tr><tr><td><p><b>Diagnosis &amp; Markers</b></p></td><td><p><b>Endometrial Biopsy (Pipelle)</b> or Hysteroscopy + D&amp;C (Type 1 = Endometrioid adenocarcinoma)</p></td><td><p><b>TVUS</b> (complex mass, septations, papillary projections, ascites) + <b>Serum CA-125</b> <i>(caution: CA-125 is elevated in endometriosis/PID/fibroids in premenopausal women -&gt; most specific in postmenopausal!)</i> -&gt; <b>Surgical Staging (NEVER needle-biopsy an isolated early ovarian mass -&gt; spills tumor!)</b></p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><b>Total Hysterectomy + Bilateral Salpingo-Oophorectomy (TAH-BSO)</b> + Lymph node staging (+/- radiation/chemo)</p></td><td><p><b>Staging Laparotomy / Debulking Surgery (TAH-BSO + Omentectomy)</b> + <b>Carboplatin + Paclitaxel</b> (+/- PARP inhibitor if BRCA+)!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u199\">← Case 28</button><button class=\"nv\" data-u=\"u201\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u201\" hidden style=\"--c:#1e6fd9\"><button class=\"back\" data-p=\"8\">← Obstetrics &amp; Gynecology</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Breast Disorders &amp; Breast Cancer Screening / RED Flags</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Breast+Disorders+%26+Breast+Cancer+Screening+%2F+RED+Flags\">🔍 Search on Google</a></header><h3><b>1. Benign vs. Malignant Breast Masses (Triple Assessment: Clinical Exam + Imaging + Biopsy!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Condition</b></p></th><th><p><b>Classic Patient &amp; Exam Findings</b></p></th><th><p><b>Management</b></p></th></tr><tr><td><p><b>Fibroadenoma</b></p></td><td><p><b>Young woman (15–30 yrs):</b> Solitary, <b>well-circumscribed, rubbery, VERY MOBILE (\"breast mouse\")</b>, non-tender mass</p></td><td><p>Ultrasound (&lt; 30–35 yrs) +/- Core Needle Biopsy -&gt; Observe or excise if growing/large (&gt; 3 cm)</p></td></tr><tr><td></td><td></td><td></td></tr><tr><td><p><b>Fibrocystic Changes</b></p></td><td><p><b>Reproductive age (30–50 yrs):</b> Bilateral <b>cyclic breast pain (mastalgia) &amp; nodularity</b> worse <b>premenstrually</b>, improves after menses</p></td><td><p>Reassurance, supportive bra, NSAIDs, Ultrasound if discrete lump (aspirate simple cyst if painful!)</p></td></tr><tr><td><p><b>Intraductal Papilloma</b></p></td><td><p><b>Unilateral bloody (or serosanguinous) nipple discharge</b> from a single duct (usually NO palpable mass!)</p></td><td><p>Mammogram/US -&gt; <b>Subareolar Duct Excision</b> (rule out DCIS/cancer!)</p></td></tr><tr><td><p><mark class=\"hl lab\"><b>Breast Cancer (Invasive Ductal Carcinoma #1)</b></mark></p></td><td><p><b>Hard, painless, irregular, fixed/immobile mass</b>, <b>skin dimpling / Peau d’Orange</b> (dermal lymphatic edema), <b>nipple retraction</b>, bloody nipple discharge, <b>axillary lymphadenopathy</b>, OR <b>eczematous scaly nipple (Paget’s Disease!)</b></p></td><td><p><b>Diagnostic Mammogram + Ultrasound</b> -&gt; <b>Core Needle Biopsy </b>(<b>ER/PR + HER2</b> status!) -&gt; Lumpectomy + Radiation OR Mastectomy + Sentinel Node Biopsy + Systemic Therapy (Chemo / Tamoxifen or Aromatase Inhibitor if ER+ / Trastuzumab if HER2+)!</p></td></tr></table><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>CRITICAL PREGNANCY/LACTATION RED FLAG — Inflammatory Breast Cancer (IBC):</b></mark> Rapidly enlarging <b>erythematous, warm, edematous breast with </b><i><b>Peau d’Orange</b></i> -&gt; <mark class=\"hl mech\"><b>IF \"mastitis\" fails to improve after 1–2 weeks of antibiotics -&gt; IMMEDIATELY PERFORM SKIN PUNCH BIOPSY TO RULE OUT INFLAMMATORY BREAST CANCER!</b></mark></li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Breast Cancer Screening:</b></mark> Average-risk women -&gt; <b>Screening Mammogram every 1–2 years starting at age 40</b> (per USPSTF 2024 / ACS guidelines).</li>\n</ul>\n<p class=\"muted\"><i>End of Part 8B — OB/GYN (30 Cases Complete!)</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u200\">← Case 29</button></nav></article>"});
